insert into learning_evidences (id, dba_id, num, texto) select 'e8a23de9-5282-4754-924f-336463acb6ba'::uuid, d.id, 1, 'Construye e interpreta representaciones pictóricas y diagramas para representar relaciones entre cantidades que se presentan en situaciones o fenómenos.' from dbas d join subjects s on s.id = d.subject_id and s.slug = 'matematicas' where d.grade = 1 and d.num = 1;
