insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('c7b459d0-f80f-4ecd-8499-b44d4004a9d7'::uuid, 'multiple_choice', '¿Cuál número dice CUÁNTOS hay?', '{"options":["5 manzanas","El piso 3","El bus 20","El teléfono 315"],"correctIndex":0,"ayuda":{"pista":"Busca el número que puedes contar con el dedo, uno por uno, hasta terminar.","pasos":["Un número no siempre cuenta cosas. A veces es un nombre: el bus 20, el piso 3, un teléfono.","Para saber si cuenta, pregúntate: ¿puedo señalarlos uno por uno y terminar?","Por ejemplo, en «5 manzanas» sí: señalas 1, 2, 3, 4, 5. En «el bus 20» no, porque no hay veinte buses."],"ojo":"El número de un bus, de un piso o de un teléfono es un nombre, no una cantidad."}}'::jsonb, 1);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('c7b459d0-f80f-4ecd-8499-b44d4004a9d7'::uuid, 'multiple_choice', '¿Cuál número dice CUÁNTOS hay?', '{"options":["7 perros en el parque","La casa número 7","El canal 7","Llegó de 7º"],"correctIndex":0,"ayuda":{"pista":"Busca el número que puedes contar con el dedo, uno por uno, hasta terminar.","pasos":["Un número no siempre cuenta cosas. A veces es un nombre: el bus 20, el piso 3, un teléfono.","Para saber si cuenta, pregúntate: ¿puedo señalarlos uno por uno y terminar?","Por ejemplo, en «5 manzanas» sí: señalas 1, 2, 3, 4, 5. En «el bus 20» no, porque no hay veinte buses."],"ojo":"El número de un bus, de un piso o de un teléfono es un nombre, no una cantidad."}}'::jsonb, 1);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('c7b459d0-f80f-4ecd-8499-b44d4004a9d7'::uuid, 'multiple_choice', '¿Cuál número dice CUÁNTOS hay?', '{"options":["3 galletas en el plato","El piso 3","La ruta 3","La talla 3"],"correctIndex":0,"ayuda":{"pista":"Busca el número que puedes contar con el dedo, uno por uno, hasta terminar.","pasos":["Un número no siempre cuenta cosas. A veces es un nombre: el bus 20, el piso 3, un teléfono.","Para saber si cuenta, pregúntate: ¿puedo señalarlos uno por uno y terminar?","Por ejemplo, en «5 manzanas» sí: señalas 1, 2, 3, 4, 5. En «el bus 20» no, porque no hay veinte buses."],"ojo":"El número de un bus, de un piso o de un teléfono es un nombre, no una cantidad."}}'::jsonb, 1);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('c7b459d0-f80f-4ecd-8499-b44d4004a9d7'::uuid, 'multiple_choice', '¿Cuál número dice EN QUÉ PUESTO llegó?', '{"options":["Llegó de 2º","Tiene 2 perros","Mide 2 metros","Vive en la casa 2"],"correctIndex":0,"ayuda":{"pista":"Busca el que dice en qué PUESTO va, no cuántos hay.","pasos":["Cuando el número dice el puesto, casi siempre se lee distinto: primero, segundo, quinto.","Por eso se escribe con esa bolita: 1º, 2º, 5º.","«Quedó de 5º» habla de UN niño y de su puesto. «Tiene 5 años» habla de una cantidad."],"ojo":"Ser el 5º no significa que haya cinco. Significa que hay cuatro adelante."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('c7b459d0-f80f-4ecd-8499-b44d4004a9d7'::uuid, 'multiple_choice', '¿Cuál número dice EN QUÉ PUESTO quedó?', '{"options":["Quedó de 5º en la fila","Tiene 5 años","Pesa 5 kilos","Compró 5 panes"],"correctIndex":0,"ayuda":{"pista":"Busca el que dice en qué PUESTO va, no cuántos hay.","pasos":["Cuando el número dice el puesto, casi siempre se lee distinto: primero, segundo, quinto.","Por eso se escribe con esa bolita: 1º, 2º, 5º.","«Quedó de 5º» habla de UN niño y de su puesto. «Tiene 5 años» habla de una cantidad."],"ojo":"Ser el 5º no significa que haya cinco. Significa que hay cuatro adelante."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('c7b459d0-f80f-4ecd-8499-b44d4004a9d7'::uuid, 'multiple_choice', '¿Cuál número dice EL ORDEN?', '{"options":["Es el 1º de la lista","Tiene 1 hermano","Mide 1 metro","Cuesta 1 peso"],"correctIndex":0,"ayuda":{"pista":"Busca el que dice en qué PUESTO va, no cuántos hay.","pasos":["Cuando el número dice el puesto, casi siempre se lee distinto: primero, segundo, quinto.","Por eso se escribe con esa bolita: 1º, 2º, 5º.","«Quedó de 5º» habla de UN niño y de su puesto. «Tiene 5 años» habla de una cantidad."],"ojo":"Ser el 5º no significa que haya cinco. Significa que hay cuatro adelante."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('c7b459d0-f80f-4ecd-8499-b44d4004a9d7'::uuid, 'multiple_choice', '¿Cuál número dice CUÁNTO MIDE?', '{"options":["Mide 3 metros","Tengo 3 primos","Vivo en el piso 3","Soy el número 3"],"correctIndex":0,"ayuda":{"pista":"Busca el número que viene con una unidad de medida: metros, kilos, minutos.","pasos":["Cuando el número mide, siempre lo acompaña una palabra que dice CON QUÉ se midió.","Metros para el largo, kilos para el peso, minutos para el tiempo.","Si el número va solo o con cosas contables (3 primos, 5 sillas), no está midiendo: está contando."],"ojo":"Busca la unidad. Sin unidad, el número no está midiendo."}}'::jsonb, 3);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('c7b459d0-f80f-4ecd-8499-b44d4004a9d7'::uuid, 'multiple_choice', '¿Cuál número dice CUÁNTO PESA?', '{"options":["Pesa 2 kilos","Tengo 2 gatos","Llegué de 2º","Vivo en el 2"],"correctIndex":0,"ayuda":{"pista":"Busca el número que viene con una unidad de medida: metros, kilos, minutos.","pasos":["Cuando el número mide, siempre lo acompaña una palabra que dice CON QUÉ se midió.","Metros para el largo, kilos para el peso, minutos para el tiempo.","Si el número va solo o con cosas contables (3 primos, 5 sillas), no está midiendo: está contando."],"ojo":"Busca la unidad. Sin unidad, el número no está midiendo."}}'::jsonb, 3);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('c7b459d0-f80f-4ecd-8499-b44d4004a9d7'::uuid, 'multiple_choice', '¿Cuál número dice CUÁNTO DURA?', '{"options":["Dura 5 minutos","Hay 5 sillas","Es el puesto 5","Tomo la ruta 5"],"correctIndex":0,"ayuda":{"pista":"Busca el número que viene con una unidad de medida: metros, kilos, minutos.","pasos":["Cuando el número mide, siempre lo acompaña una palabra que dice CON QUÉ se midió.","Metros para el largo, kilos para el peso, minutos para el tiempo.","Si el número va solo o con cosas contables (3 primos, 5 sillas), no está midiendo: está contando."],"ojo":"Busca la unidad. Sin unidad, el número no está midiendo."}}'::jsonb, 3);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('c7b459d0-f80f-4ecd-8499-b44d4004a9d7'::uuid, 'multiple_choice', 'El número de tu casa sirve para:', '{"options":["Saber cuál casa es","Contar las casas","Medir la casa","Pesar la casa"],"correctIndex":0,"ayuda":{"pista":"Pregúntate para qué le pusieron ese número: casi siempre es para distinguirlo de los demás.","pasos":["Hay números que son como un nombre: sirven para saber CUÁL es, no cuántos hay.","La casa 20 no es la casa número veinte de la cuadra necesariamente: es LA casa 20.","Por eso no se pueden sumar: sumar dos números de camiseta no da nada que signifique algo."],"ojo":"Un número que es un nombre no sirve para contar, ni para medir, ni para sumar."}}'::jsonb, 4);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('c7b459d0-f80f-4ecd-8499-b44d4004a9d7'::uuid, 'multiple_choice', 'El número de una camiseta sirve para:', '{"options":["Saber quién es el jugador","Contar los jugadores","Medir la camiseta","Pesar la camiseta"],"correctIndex":0,"ayuda":{"pista":"Pregúntate para qué le pusieron ese número: casi siempre es para distinguirlo de los demás.","pasos":["Hay números que son como un nombre: sirven para saber CUÁL es, no cuántos hay.","La casa 20 no es la casa número veinte de la cuadra necesariamente: es LA casa 20.","Por eso no se pueden sumar: sumar dos números de camiseta no da nada que signifique algo."],"ojo":"Un número que es un nombre no sirve para contar, ni para medir, ni para sumar."}}'::jsonb, 4);
