insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('7e1c8fcb-37c0-4ef9-b062-7fbe593658a7'::uuid, 'multiple_choice', 'Al bus se suben 3 niños. Para saber cuántos hay ahora:', '{"options":["Sumo","Resto","Cuento hacia atrás","No hago nada"],"correctIndex":0,"ayuda":{"pista":"Fíjate si en la historia algo LLEGA o algo SE VA. Eso decide la operación.","pasos":["Lee la historia y busca el verbo: subirse, meter, llegar, regalar, echar.","Si algo llega o se agrega, la cantidad crece: se suma.","Si algo se va, se pierde o se come, la cantidad baja: se resta."],"ojo":"No todas las historias de este tema se suman. Lee qué pasó antes de decidir."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('7e1c8fcb-37c0-4ef9-b062-7fbe593658a7'::uuid, 'multiple_choice', 'Del bus se bajan 3 niños. Para saber cuántos quedan:', '{"options":["Resto","Sumo","Cuento hacia adelante","No hago nada"],"correctIndex":0,"ayuda":{"pista":"Fíjate si en la historia algo LLEGA o algo SE VA. Eso decide la operación.","pasos":["Lee la historia y busca el verbo: subirse, meter, llegar, regalar, echar.","Si algo llega o se agrega, la cantidad crece: se suma.","Si algo se va, se pierde o se come, la cantidad baja: se resta."],"ojo":"No todas las historias de este tema se suman. Lee qué pasó antes de decidir."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('7e1c8fcb-37c0-4ef9-b062-7fbe593658a7'::uuid, 'multiple_choice', 'Metes 2 lápices más a la cartuchera. Para saber cuántos hay:', '{"options":["Sumo","Resto","Cuento hacia atrás","Los saco"],"correctIndex":0,"ayuda":{"pista":"Fíjate si en la historia algo LLEGA o algo SE VA. Eso decide la operación.","pasos":["Lee la historia y busca el verbo: subirse, meter, llegar, regalar, echar.","Si algo llega o se agrega, la cantidad crece: se suma.","Si algo se va, se pierde o se come, la cantidad baja: se resta."],"ojo":"No todas las historias de este tema se suman. Lee qué pasó antes de decidir."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('7e1c8fcb-37c0-4ef9-b062-7fbe593658a7'::uuid, 'multiple_choice', 'De la caja se pierden 4 crayolas. Para saber cuántas quedan:', '{"options":["Resto","Sumo","Cuento hacia adelante","No hago nada"],"correctIndex":0,"ayuda":{"pista":"Fíjate si en la historia algo LLEGA o algo SE VA. Eso decide la operación.","pasos":["Busca el verbo de la historia: perderse, irse, comerse, bajarse… o llegar y echar.","Si algo desaparece, quedan menos: se resta.","Si algo aparece, hay más: se suma."],"ojo":"Ojo con esta: aquí también hay historias en las que la cantidad crece."}}'::jsonb, 10);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('7e1c8fcb-37c0-4ef9-b062-7fbe593658a7'::uuid, 'multiple_choice', 'Llegan 5 galletas más al paquete. Para saber cuántas hay:', '{"options":["Sumo","Resto","Cuento hacia atrás","Abro otro"],"correctIndex":0,"ayuda":{"pista":"Fíjate si en la historia algo LLEGA o algo SE VA. Eso decide la operación.","pasos":["Busca el verbo de la historia: perderse, irse, comerse, bajarse… o llegar y echar.","Si algo desaparece, quedan menos: se resta.","Si algo aparece, hay más: se suma."],"ojo":"Ojo con esta: aquí también hay historias en las que la cantidad crece."}}'::jsonb, 10);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('7e1c8fcb-37c0-4ef9-b062-7fbe593658a7'::uuid, 'multiple_choice', 'Se van 3 niños del salón. Para saber cuántos quedan:', '{"options":["Resto","Sumo","Cuento hacia adelante","Los llamo"],"correctIndex":0,"ayuda":{"pista":"Fíjate si en la historia algo LLEGA o algo SE VA. Eso decide la operación.","pasos":["Busca el verbo de la historia: perderse, irse, comerse, bajarse… o llegar y echar.","Si algo desaparece, quedan menos: se resta.","Si algo aparece, hay más: se suma."],"ojo":"Ojo con esta: aquí también hay historias en las que la cantidad crece."}}'::jsonb, 10);
