insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('08ac9231-c039-4e37-8b2d-00a725aabde5'::uuid, 'multiple_choice', '¿Cuántos dieces necesitas para armar 30?', '{"options":["3","30","13","10"],"correctIndex":0,"ayuda":{"pista":"Un diez es un montón de diez. Cuenta cuántos montones completos caben.","pasos":["Los números se arman con montones de diez y con unos sueltos.","Para saber cuántos dieces hay en 30, cuenta de 10 en 10: 10, 20, 30. Contaste 3.","Y al revés: 4 dieces y 2 unos se escriben poniendo primero los dieces y después los unos."],"ojo":"4 dieces y 2 unos no se escribe 402. El 4 ya está diciendo que son cuarenta."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('08ac9231-c039-4e37-8b2d-00a725aabde5'::uuid, 'multiple_choice', '¿Cuántos dieces necesitas para armar 50?', '{"options":["5","50","15","10"],"correctIndex":0,"ayuda":{"pista":"Un diez es un montón de diez. Cuenta cuántos montones completos caben.","pasos":["Los números se arman con montones de diez y con unos sueltos.","Para saber cuántos dieces hay en 30, cuenta de 10 en 10: 10, 20, 30. Contaste 3.","Y al revés: 4 dieces y 2 unos se escriben poniendo primero los dieces y después los unos."],"ojo":"4 dieces y 2 unos no se escribe 402. El 4 ya está diciendo que son cuarenta."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('08ac9231-c039-4e37-8b2d-00a725aabde5'::uuid, 'multiple_choice', 'Con 4 dieces y 2 unos armas el número:', '{"options":["42","24","6","402"],"correctIndex":0,"ayuda":{"pista":"Un diez es un montón de diez. Cuenta cuántos montones completos caben.","pasos":["Los números se arman con montones de diez y con unos sueltos.","Para saber cuántos dieces hay en 30, cuenta de 10 en 10: 10, 20, 30. Contaste 3.","Y al revés: 4 dieces y 2 unos se escriben poniendo primero los dieces y después los unos."],"ojo":"4 dieces y 2 unos no se escribe 402. El 4 ya está diciendo que son cuarenta."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('080a0449-689e-48ef-a049-3fe18b79f9be'::uuid, 'multiple_choice', 'En 2, 4, 6, 8... todos los números son:', '{"options":["Pares","Impares","Unos pares y otros no","Mayores que 10"],"correctIndex":0,"ayuda":{"pista":"Mira los números de la lista y busca qué tienen TODOS en común, no solo el primero.","pasos":["Una conjetura es darse cuenta de algo que se repite siempre.","Mira la lista entera, no un número suelto. ¿En qué terminan? ¿Se pueden repartir en dos montones iguales?","Los que se reparten en dos montones iguales son pares; los que dejan uno suelto son impares."],"ojo":"Que el primero cumpla no basta: la regla tiene que valer para todos."}}'::jsonb, 10);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('080a0449-689e-48ef-a049-3fe18b79f9be'::uuid, 'multiple_choice', 'En 1, 3, 5, 7... todos los números son:', '{"options":["Impares","Pares","Unos pares y otros no","Menores que 3"],"correctIndex":0,"ayuda":{"pista":"Mira los números de la lista y busca qué tienen TODOS en común, no solo el primero.","pasos":["Una conjetura es darse cuenta de algo que se repite siempre.","Mira la lista entera, no un número suelto. ¿En qué terminan? ¿Se pueden repartir en dos montones iguales?","Los que se reparten en dos montones iguales son pares; los que dejan uno suelto son impares."],"ojo":"Que el primero cumpla no basta: la regla tiene que valer para todos."}}'::jsonb, 10);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('080a0449-689e-48ef-a049-3fe18b79f9be'::uuid, 'multiple_choice', 'En 5, 10, 15, 20... todos terminan en:', '{"options":["5 o en 0","1 o en 2","3 o en 4","7 o en 9"],"correctIndex":0,"ayuda":{"pista":"Mira los números de la lista y busca qué tienen TODOS en común, no solo el primero.","pasos":["Una conjetura es darse cuenta de algo que se repite siempre.","Mira la lista entera, no un número suelto. ¿En qué terminan? ¿Se pueden repartir en dos montones iguales?","Los que se reparten en dos montones iguales son pares; los que dejan uno suelto son impares."],"ojo":"Que el primero cumpla no basta: la regla tiene que valer para todos."}}'::jsonb, 10);
insert into learning_evidences (id, dba_id, num, texto) select '1e3a2469-2880-4a9e-bc28-ce0ecbd60bf7'::uuid, d.id, 1, 'Realiza composiciones y descomposiciones de números de dos dígitos en términos de la cantidad de "dieces" y de "unos" que los conforman.' from dbas d join subjects s on s.id = d.subject_id and s.slug = 'matematicas' where d.grade = 1 and d.num = 3;
