insert into learning_evidences (id, dba_id, num, texto) select '56cfd17d-84f8-4df1-a330-63097f9c8a2c'::uuid, d.id, 4, 'Emplea estrategias de cálculo como "el paso por el diez" para realizar adiciones o sustracciones.' from dbas d join subjects s on s.id = d.subject_id and s.slug = 'matematicas' where d.grade = 1 and d.num = 3;
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('1e3a2469-2880-4a9e-bc28-ce0ecbd60bf7'::uuid, 'multiple_choice', '¿Qué número tiene 5 decenas y 2 unidades?', '{"options":["52","25","502","7"],"correctIndex":0,"visual":{"tipo":"decenas","decenas":5,"unidades":2},"ayuda":{"pista":"El número de dieces se escribe primero, y el de unos, de segundo.","pasos":["En un número de dos cifras, la de la izquierda dice cuántos DIECES hay.","La de la derecha dice cuántos UNOS sueltos quedan.","Por ejemplo, 5 decenas y 2 unidades se escribe 52: primero el 5, después el 2."],"ojo":"No se escriben pegados como 502, ni se suman como 5 + 2 = 7. El 5 vale cincuenta."}}'::jsonb, 1);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('1e3a2469-2880-4a9e-bc28-ce0ecbd60bf7'::uuid, 'multiple_choice', '¿Qué número tiene 3 decenas y 6 unidades?', '{"options":["36","63","306","9"],"correctIndex":0,"visual":{"tipo":"decenas","decenas":3,"unidades":6},"ayuda":{"pista":"El número de dieces se escribe primero, y el de unos, de segundo.","pasos":["En un número de dos cifras, la de la izquierda dice cuántos DIECES hay.","La de la derecha dice cuántos UNOS sueltos quedan.","Por ejemplo, 5 decenas y 2 unidades se escribe 52: primero el 5, después el 2."],"ojo":"No se escriben pegados como 502, ni se suman como 5 + 2 = 7. El 5 vale cincuenta."}}'::jsonb, 1);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('1e3a2469-2880-4a9e-bc28-ce0ecbd60bf7'::uuid, 'multiple_choice', '¿Qué número tiene 8 decenas y 1 unidad?', '{"options":["81","18","801","9"],"correctIndex":0,"visual":{"tipo":"decenas","decenas":8,"unidades":1},"ayuda":{"pista":"El número de dieces se escribe primero, y el de unos, de segundo.","pasos":["En un número de dos cifras, la de la izquierda dice cuántos DIECES hay.","La de la derecha dice cuántos UNOS sueltos quedan.","Por ejemplo, 5 decenas y 2 unidades se escribe 52: primero el 5, después el 2."],"ojo":"No se escriben pegados como 502, ni se suman como 5 + 2 = 7. El 5 vale cincuenta."}}'::jsonb, 1);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('1e3a2469-2880-4a9e-bc28-ce0ecbd60bf7'::uuid, 'multiple_choice', 'El número 34 tiene:', '{"options":["3 decenas y 4 unidades","4 decenas y 3 unidades","34 decenas","3 unidades y 4 decenas"],"correctIndex":0,"visual":{"tipo":"decenas","decenas":3,"unidades":4},"ayuda":{"pista":"Lee el número de izquierda a derecha: la primera cifra son los dieces.","pasos":["Tapa la última cifra con el dedo. Lo que queda son los dieces.","Destapa: esa última cifra son los unos sueltos.","Por ejemplo, en 34: el 3 son 3 dieces (treinta) y el 4 son 4 unos."],"ojo":"El orden importa. 34 y 43 tienen las mismas cifras y no valen lo mismo."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('1e3a2469-2880-4a9e-bc28-ce0ecbd60bf7'::uuid, 'multiple_choice', 'El número 47 tiene:', '{"options":["4 decenas y 7 unidades","7 decenas y 4 unidades","47 decenas","4 unidades y 7 decenas"],"correctIndex":0,"visual":{"tipo":"decenas","decenas":4,"unidades":7},"ayuda":{"pista":"Lee el número de izquierda a derecha: la primera cifra son los dieces.","pasos":["Tapa la última cifra con el dedo. Lo que queda son los dieces.","Destapa: esa última cifra son los unos sueltos.","Por ejemplo, en 34: el 3 son 3 dieces (treinta) y el 4 son 4 unos."],"ojo":"El orden importa. 34 y 43 tienen las mismas cifras y no valen lo mismo."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('1e3a2469-2880-4a9e-bc28-ce0ecbd60bf7'::uuid, 'multiple_choice', 'El número 29 tiene:', '{"options":["2 decenas y 9 unidades","9 decenas y 2 unidades","29 decenas","2 unidades y 9 decenas"],"correctIndex":0,"visual":{"tipo":"decenas","decenas":2,"unidades":9},"ayuda":{"pista":"Lee el número de izquierda a derecha: la primera cifra son los dieces.","pasos":["Tapa la última cifra con el dedo. Lo que queda son los dieces.","Destapa: esa última cifra son los unos sueltos.","Por ejemplo, en 34: el 3 son 3 dieces (treinta) y el 4 son 4 unos."],"ojo":"El orden importa. 34 y 43 tienen las mismas cifras y no valen lo mismo."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('1e3a2469-2880-4a9e-bc28-ce0ecbd60bf7'::uuid, 'multiple_choice', 'El número 70 tiene:', '{"options":["7 decenas y 0 unidades","0 decenas y 7 unidades","7 unidades","70 decenas"],"correctIndex":0,"visual":{"tipo":"decenas","decenas":7,"unidades":0},"ayuda":{"pista":"Un cero en los unos quiere decir que no sobró ninguno suelto.","pasos":["Los números que terminan en 0 son dieces exactos: no quedó ningún uno suelto.","Por ejemplo, 70 son 7 dieces y 0 unos.","Por eso se cuentan de 10 en 10: 10, 20, 30… y siempre caen justo."],"ojo":"70 no son 7 unidades. El 0 está diciendo que el 7 son dieces."}}'::jsonb, 3);
