insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('dcf1e2f6-5bce-4848-8b2f-5a743965840f'::uuid, 'multiple_choice', '¿Cuál pareja suma 10?', '{"options":["6 y 4","6 y 3","5 y 6","8 y 3"],"correctIndex":0,"ayuda":{"pista":"Prueba cada pareja: cuenta desde el primer número hasta ver si llegas justo a 10.","pasos":["Las parejas que suman 10 hay que aprendérselas, porque se usan todo el tiempo.","Son: 1 y 9, 2 y 8, 3 y 7, 4 y 6, y 5 con 5.","Fíjate que cuando una sube, la otra baja: si tienes más de una, necesitas menos de la otra."],"ojo":"Revisa todas las parejas antes de elegir: varias se parecen y solo una da justo 10."}}'::jsonb, 4);
