insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('7b257a7e-986c-43c2-921f-61e82430f6ae'::uuid, 'multiple_choice', 'Diez más que 63 es:', '{"options":["73","64","53","630"],"correctIndex":0,"ayuda":{"pista":"Diez más o diez menos cambia SOLO la cifra de los dieces. La de los unos queda igual.","pasos":["Sumar diez es agregar un montón de diez completo, no unos sueltos.","Por eso la última cifra no se mueve: si tenías 63, sigues teniendo 3 unos.","Lo que cambia es la primera: 6 dieces pasan a ser 7. Queda 73."],"ojo":"Diez más no es ponerle un cero. 63 y diez más es 73, no 630."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('7b257a7e-986c-43c2-921f-61e82430f6ae'::uuid, 'multiple_choice', 'Diez más que 28 es:', '{"options":["38","29","18","280"],"correctIndex":0,"ayuda":{"pista":"Diez más o diez menos cambia SOLO la cifra de los dieces. La de los unos queda igual.","pasos":["Sumar diez es agregar un montón de diez completo, no unos sueltos.","Por eso la última cifra no se mueve: si tenías 63, sigues teniendo 3 unos.","Lo que cambia es la primera: 6 dieces pasan a ser 7. Queda 73."],"ojo":"Diez más no es ponerle un cero. 63 y diez más es 73, no 630."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('7b257a7e-986c-43c2-921f-61e82430f6ae'::uuid, 'multiple_choice', 'Diez menos que 45 es:', '{"options":["35","44","55","450"],"correctIndex":0,"ayuda":{"pista":"Diez más o diez menos cambia SOLO la cifra de los dieces. La de los unos queda igual.","pasos":["Sumar diez es agregar un montón de diez completo, no unos sueltos.","Por eso la última cifra no se mueve: si tenías 63, sigues teniendo 3 unos.","Lo que cambia es la primera: 6 dieces pasan a ser 7. Queda 73."],"ojo":"Diez más no es ponerle un cero. 63 y diez más es 73, no 630."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('dcf1e2f6-5bce-4848-8b2f-5a743965840f'::uuid, 'multiple_choice', '¿Cuál pareja suma 20?', '{"options":["15 y 5","15 y 10","12 y 6","10 y 5"],"correctIndex":0,"ayuda":{"pista":"Suma cada pareja y compárala con el número que te piden. Solo una da justo.","pasos":["Empieza por el número más grande de la pareja y cuéntale el otro hacia adelante.","Por ejemplo, para 15 y 5: empiezas en 15 y cuentas 5 más: 16, 17, 18, 19, 20.","Si te pasas o te quedas corto, esa pareja no es."],"ojo":"Aquí no siempre piden 20. Lee primero a qué número tiene que llegar la pareja."}}'::jsonb, 10);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('dcf1e2f6-5bce-4848-8b2f-5a743965840f'::uuid, 'multiple_choice', '¿Cuál pareja suma 20?', '{"options":["12 y 8","12 y 10","14 y 5","11 y 8"],"correctIndex":0,"ayuda":{"pista":"Suma cada pareja y compárala con el número que te piden. Solo una da justo.","pasos":["Empieza por el número más grande de la pareja y cuéntale el otro hacia adelante.","Por ejemplo, para 15 y 5: empiezas en 15 y cuentas 5 más: 16, 17, 18, 19, 20.","Si te pasas o te quedas corto, esa pareja no es."],"ojo":"Aquí no siempre piden 20. Lee primero a qué número tiene que llegar la pareja."}}'::jsonb, 10);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('dcf1e2f6-5bce-4848-8b2f-5a743965840f'::uuid, 'multiple_choice', '¿Cuál pareja suma 15?', '{"options":["10 y 5","10 y 10","9 y 5","8 y 6"],"correctIndex":0,"ayuda":{"pista":"Suma cada pareja y compárala con el número que te piden. Solo una da justo.","pasos":["Empieza por el número más grande de la pareja y cuéntale el otro hacia adelante.","Por ejemplo, para 15 y 5: empiezas en 15 y cuentas 5 más: 16, 17, 18, 19, 20.","Si te pasas o te quedas corto, esa pareja no es."],"ojo":"Aquí no siempre piden 20. Lee primero a qué número tiene que llegar la pareja."}}'::jsonb, 10);
insert into learning_evidences (id, dba_id, num, texto) select '576db92e-0ca2-4828-8f59-2b832d96f0d3'::uuid, d.id, 1, 'Identifica atributos que se pueden medir en los objetos.' from dbas d join subjects s on s.id = d.subject_id and s.slug = 'matematicas' where d.grade = 1 and d.num = 4;
