insert into learning_evidences (id, dba_id, num, texto) select '3d6f9e53-46d4-4f27-ab3c-3feea7faefd0'::uuid, d.id, 3, 'Compara y ordena objetos de acuerdo con atributos como altura, peso, intensidades de color, entre otros y recorridos según la distancia de cada trayecto.' from dbas d join subjects s on s.id = d.subject_id and s.slug = 'matematicas' where d.grade = 1 and d.num = 4;
insert into learning_evidences (id, dba_id, num, texto) select '2c8f6439-81b2-4166-a57a-1cca495ae581'::uuid, d.id, 4, 'Compara y ordena colecciones según la cantidad de elementos.' from dbas d join subjects s on s.id = d.subject_id and s.slug = 'matematicas' where d.grade = 1 and d.num = 4;
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('2c8f6439-81b2-4166-a57a-1cca495ae581'::uuid, 'multiple_choice', '¿Cuál grupo tiene MÁS?', '{"options":["8 estrellas","6 estrellas","5 estrellas","3 estrellas"],"correctIndex":0,"ayuda":{"pista":"El que tiene MÁS es el número más grande. Compáralos de a dos.","pasos":["Todos los grupos son de lo mismo, así que basta comparar los números.","Compáralos de a dos y quédate siempre con el más grande.","El que gane todas las comparaciones es el que tiene más."],"ojo":"Lee si te preguntan MÁS o MENOS. Es lo único que cambia entre las dos preguntas."}}'::jsonb, 1);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('2c8f6439-81b2-4166-a57a-1cca495ae581'::uuid, 'multiple_choice', '¿Cuál grupo tiene MÁS?', '{"options":["9 bolas","7 bolas","4 bolas","2 bolas"],"correctIndex":0,"ayuda":{"pista":"El que tiene MÁS es el número más grande. Compáralos de a dos.","pasos":["Todos los grupos son de lo mismo, así que basta comparar los números.","Compáralos de a dos y quédate siempre con el más grande.","El que gane todas las comparaciones es el que tiene más."],"ojo":"Lee si te preguntan MÁS o MENOS. Es lo único que cambia entre las dos preguntas."}}'::jsonb, 1);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('2c8f6439-81b2-4166-a57a-1cca495ae581'::uuid, 'multiple_choice', '¿Cuál grupo tiene MÁS?', '{"options":["12 fichas","10 fichas","8 fichas","6 fichas"],"correctIndex":0,"ayuda":{"pista":"El que tiene MÁS es el número más grande. Compáralos de a dos.","pasos":["Todos los grupos son de lo mismo, así que basta comparar los números.","Compáralos de a dos y quédate siempre con el más grande.","El que gane todas las comparaciones es el que tiene más."],"ojo":"Lee si te preguntan MÁS o MENOS. Es lo único que cambia entre las dos preguntas."}}'::jsonb, 1);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('2c8f6439-81b2-4166-a57a-1cca495ae581'::uuid, 'multiple_choice', '¿Cuál grupo tiene MENOS?', '{"options":["2 flores","5 flores","7 flores","9 flores"],"correctIndex":0,"ayuda":{"pista":"El que tiene MENOS es el número más pequeño. Compáralos de a dos.","pasos":["Como todos los grupos son de lo mismo, se comparan los números directamente.","Ve de a dos y quédate siempre con el más pequeño.","El que gane todas las comparaciones es el que tiene menos."],"ojo":"Aquí piden MENOS. Contestar con el número más grande es el error de siempre."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('2c8f6439-81b2-4166-a57a-1cca495ae581'::uuid, 'multiple_choice', '¿Cuál grupo tiene MENOS?', '{"options":["3 lápices","6 lápices","8 lápices","11 lápices"],"correctIndex":0,"ayuda":{"pista":"El que tiene MENOS es el número más pequeño. Compáralos de a dos.","pasos":["Como todos los grupos son de lo mismo, se comparan los números directamente.","Ve de a dos y quédate siempre con el más pequeño.","El que gane todas las comparaciones es el que tiene menos."],"ojo":"Aquí piden MENOS. Contestar con el número más grande es el error de siempre."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('2c8f6439-81b2-4166-a57a-1cca495ae581'::uuid, 'multiple_choice', '¿Cuál grupo tiene MENOS?', '{"options":["1 galleta","4 galletas","7 galletas","10 galletas"],"correctIndex":0,"ayuda":{"pista":"El que tiene MENOS es el número más pequeño. Compáralos de a dos.","pasos":["Como todos los grupos son de lo mismo, se comparan los números directamente.","Ve de a dos y quédate siempre con el más pequeño.","El que gane todas las comparaciones es el que tiene menos."],"ojo":"Aquí piden MENOS. Contestar con el número más grande es el error de siempre."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('576db92e-0ca2-4828-8f59-2b832d96f0d3'::uuid, 'multiple_choice', '¿Qué se puede medir de una cuerda?', '{"options":["Su largo","Su color","Su nombre","Su dueño"],"correctIndex":0,"ayuda":{"pista":"Se puede medir lo que tiene MÁS o MENOS. Lo que solo tiene un nombre, no.","pasos":["Medir es poner un número: 3 metros, 2 kilos, 5 minutos.","Pregúntate: ¿esto puede tener más o menos? El largo sí, el peso sí, la duración sí.","El nombre y el color no: una cuerda no tiene «más nombre» que otra."],"ojo":"Que algo se pueda ver o decir no significa que se pueda medir."}}'::jsonb, 3);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('576db92e-0ca2-4828-8f59-2b832d96f0d3'::uuid, 'multiple_choice', '¿Qué se puede medir de una piedra?', '{"options":["Su peso","Su nombre","Si es bonita","Su sabor"],"correctIndex":0,"ayuda":{"pista":"Se puede medir lo que tiene MÁS o MENOS. Lo que solo tiene un nombre, no.","pasos":["Medir es poner un número: 3 metros, 2 kilos, 5 minutos.","Pregúntate: ¿esto puede tener más o menos? El largo sí, el peso sí, la duración sí.","El nombre y el color no: una cuerda no tiene «más nombre» que otra."],"ojo":"Que algo se pueda ver o decir no significa que se pueda medir."}}'::jsonb, 3);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('576db92e-0ca2-4828-8f59-2b832d96f0d3'::uuid, 'multiple_choice', '¿Qué se puede medir de una canción?', '{"options":["Cuánto dura","Su color","Su peso","Su sabor"],"correctIndex":0,"ayuda":{"pista":"Se puede medir lo que tiene MÁS o MENOS. Lo que solo tiene un nombre, no.","pasos":["Medir es poner un número: 3 metros, 2 kilos, 5 minutos.","Pregúntate: ¿esto puede tener más o menos? El largo sí, el peso sí, la duración sí.","El nombre y el color no: una cuerda no tiene «más nombre» que otra."],"ojo":"Que algo se pueda ver o decir no significa que se pueda medir."}}'::jsonb, 3);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('576db92e-0ca2-4828-8f59-2b832d96f0d3'::uuid, 'multiple_choice', '¿Qué se puede medir de una caja de jugo?', '{"options":["Cuánto le cabe","Su marca","Su sabor","Su dibujo"],"correctIndex":0,"ayuda":{"pista":"Cuando algo es un recipiente, lo que se mide es CUÁNTO LE CABE adentro.","pasos":["Las cosas huecas —una botella, una olla, un salón— guardan otras cosas adentro.","Eso que les cabe se llama capacidad, y se mide llenándolas.","Se mide con lo que quepa: vasos de agua, pocillos de arroz, niños en un salón."],"ojo":"La marca, el color o el dibujo del envase no son cosas que se midan."}}'::jsonb, 4);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('576db92e-0ca2-4828-8f59-2b832d96f0d3'::uuid, 'multiple_choice', '¿Qué se puede medir de una botella?', '{"options":["Cuánta agua le cabe","Su marca","Su color","Su tapa"],"correctIndex":0,"ayuda":{"pista":"Cuando algo es un recipiente, lo que se mide es CUÁNTO LE CABE adentro.","pasos":["Las cosas huecas —una botella, una olla, un salón— guardan otras cosas adentro.","Eso que les cabe se llama capacidad, y se mide llenándolas.","Se mide con lo que quepa: vasos de agua, pocillos de arroz, niños en un salón."],"ojo":"La marca, el color o el dibujo del envase no son cosas que se midan."}}'::jsonb, 4);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('576db92e-0ca2-4828-8f59-2b832d96f0d3'::uuid, 'multiple_choice', '¿Qué se puede medir de un salón?', '{"options":["Cuántos niños caben","Su nombre","Su color","Su profe"],"correctIndex":0,"ayuda":{"pista":"Cuando algo es un recipiente, lo que se mide es CUÁNTO LE CABE adentro.","pasos":["Las cosas huecas —una botella, una olla, un salón— guardan otras cosas adentro.","Eso que les cabe se llama capacidad, y se mide llenándolas.","Se mide con lo que quepa: vasos de agua, pocillos de arroz, niños en un salón."],"ojo":"La marca, el color o el dibujo del envase no son cosas que se midan."}}'::jsonb, 4);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('3d6f9e53-46d4-4f27-ab3c-3feea7faefd0'::uuid, 'multiple_choice', '¿Cuál es el MÁS CORTO?', '{"options":["Un clip","Un lápiz","Una regla","Una escoba"],"correctIndex":0,"ayuda":{"pista":"Imagínalos todos juntos, uno al lado del otro. Ahí se ve cuál sobresale.","pasos":["Para comparar el largo o el alto, imagina los objetos puestos uno al lado del otro.","Ordénalos de mentiras, del más pequeño al más grande.","El que te piden es el que queda en una de las dos puntas de esa fila."],"ojo":"Fíjate bien si piden el MÁS o el MENOS antes de contestar."}}'::jsonb, 5);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('3d6f9e53-46d4-4f27-ab3c-3feea7faefd0'::uuid, 'multiple_choice', '¿Cuál es el MÁS LARGO?', '{"options":["Un bus","Una bicicleta","Un patín","Un zapato"],"correctIndex":0,"ayuda":{"pista":"Imagínalos todos juntos, uno al lado del otro. Ahí se ve cuál sobresale.","pasos":["Para comparar el largo o el alto, imagina los objetos puestos uno al lado del otro.","Ordénalos de mentiras, del más pequeño al más grande.","El que te piden es el que queda en una de las dos puntas de esa fila."],"ojo":"Fíjate bien si piden el MÁS o el MENOS antes de contestar."}}'::jsonb, 5);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('3d6f9e53-46d4-4f27-ab3c-3feea7faefd0'::uuid, 'multiple_choice', '¿Cuál es el MÁS ALTO?', '{"options":["Un árbol","Una silla","Un perro","Una hormiga"],"correctIndex":0,"ayuda":{"pista":"Imagínalos todos juntos, uno al lado del otro. Ahí se ve cuál sobresale.","pasos":["Para comparar el largo o el alto, imagina los objetos puestos uno al lado del otro.","Ordénalos de mentiras, del más pequeño al más grande.","El que te piden es el que queda en una de las dos puntas de esa fila."],"ojo":"Fíjate bien si piden el MÁS o el MENOS antes de contestar."}}'::jsonb, 5);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('3d6f9e53-46d4-4f27-ab3c-3feea7faefd0'::uuid, 'multiple_choice', '¿Cuál pesa MÁS?', '{"options":["Un balde de agua","Un vaso de agua","Una cuchara de agua","Una gota de agua"],"correctIndex":0,"ayuda":{"pista":"Imagina que los cargas en las manos. El que te hunde el brazo pesa más.","pasos":["El peso no se ve: se siente. Imagina que levantas cada cosa.","Casi siempre, si es de lo mismo, la más grande pesa más: un balde de agua pesa más que un vaso de agua.","Ordénalos de mentiras del más liviano al más pesado y elige la punta que te piden."],"ojo":"Grande no siempre es pesado, pero cuando son de lo MISMO, sí."}}'::jsonb, 6);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('3d6f9e53-46d4-4f27-ab3c-3feea7faefd0'::uuid, 'multiple_choice', '¿Cuál pesa MÁS?', '{"options":["Un bulto de papas","Una bolsa de papas","Una papa","Un pedazo de papa"],"correctIndex":0,"ayuda":{"pista":"Imagina que los cargas en las manos. El que te hunde el brazo pesa más.","pasos":["El peso no se ve: se siente. Imagina que levantas cada cosa.","Casi siempre, si es de lo mismo, la más grande pesa más: un balde de agua pesa más que un vaso de agua.","Ordénalos de mentiras del más liviano al más pesado y elige la punta que te piden."],"ojo":"Grande no siempre es pesado, pero cuando son de lo MISMO, sí."}}'::jsonb, 6);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('3d6f9e53-46d4-4f27-ab3c-3feea7faefd0'::uuid, 'multiple_choice', '¿Cuál pesa MENOS?', '{"options":["Una hoja de papel","Un cuaderno","Un libro","Una maleta"],"correctIndex":0,"ayuda":{"pista":"Imagina que los cargas en las manos. El que te hunde el brazo pesa más.","pasos":["El peso no se ve: se siente. Imagina que levantas cada cosa.","Casi siempre, si es de lo mismo, la más grande pesa más: un balde de agua pesa más que un vaso de agua.","Ordénalos de mentiras del más liviano al más pesado y elige la punta que te piden."],"ojo":"Grande no siempre es pesado, pero cuando son de lo MISMO, sí."}}'::jsonb, 6);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('a4a04c77-67fa-4470-a795-f71adb915327'::uuid, 'multiple_choice', '¿Con qué sabes cuánto PESA una fruta?', '{"options":["Con una balanza","Con una regla","Con un reloj","Con un vaso"],"correctIndex":0,"ayuda":{"pista":"Cada instrumento sirve para una sola cosa. Fíjate qué te están pidiendo medir.","pasos":["La balanza pesa. El metro y la regla miden el largo. El reloj mide el tiempo.","Lee la pregunta y subraya con el dedo qué piden: ¿pesa, mide o dura?","Elige el instrumento que sirve para eso."],"ojo":"Con una regla no se puede pesar, por grande que sea la regla."}}'::jsonb, 7);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('a4a04c77-67fa-4470-a795-f71adb915327'::uuid, 'multiple_choice', '¿Con qué sabes cuánto PESA un bulto?', '{"options":["Con una balanza","Con un metro","Con un reloj","Con una jarra"],"correctIndex":0,"ayuda":{"pista":"Cada instrumento sirve para una sola cosa. Fíjate qué te están pidiendo medir.","pasos":["La balanza pesa. El metro y la regla miden el largo. El reloj mide el tiempo.","Lee la pregunta y subraya con el dedo qué piden: ¿pesa, mide o dura?","Elige el instrumento que sirve para eso."],"ojo":"Con una regla no se puede pesar, por grande que sea la regla."}}'::jsonb, 7);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('a4a04c77-67fa-4470-a795-f71adb915327'::uuid, 'multiple_choice', '¿Con qué sabes cuánto MIDE una mesa?', '{"options":["Con un metro","Con una balanza","Con un reloj","Con un vaso"],"correctIndex":0,"ayuda":{"pista":"Cada instrumento sirve para una sola cosa. Fíjate qué te están pidiendo medir.","pasos":["La balanza pesa. El metro y la regla miden el largo. El reloj mide el tiempo.","Lee la pregunta y subraya con el dedo qué piden: ¿pesa, mide o dura?","Elige el instrumento que sirve para eso."],"ojo":"Con una regla no se puede pesar, por grande que sea la regla."}}'::jsonb, 7);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('a4a04c77-67fa-4470-a795-f71adb915327'::uuid, 'multiple_choice', '¿Con qué sabes cuánto DURA un juego?', '{"options":["Con un reloj","Con una regla","Con una balanza","Con un vaso"],"correctIndex":0,"ayuda":{"pista":"Cuando la pregunta dice CUÁNTO DURA o QUÉ DÍA, lo que se mide es tiempo.","pasos":["El tiempo corto —un juego, una clase— se mide con un reloj.","El tiempo largo —los días, las semanas— se mira en un calendario.","Ni la balanza ni la regla sirven: el tiempo no pesa ni tiene largo."],"ojo":"Un reloj y un calendario miden los dos el tiempo, pero uno corto y el otro largo."}}'::jsonb, 8);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('a4a04c77-67fa-4470-a795-f71adb915327'::uuid, 'multiple_choice', '¿Con qué sabes cuánto DURA una clase?', '{"options":["Con un reloj","Con un metro","Con una balanza","Con una jarra"],"correctIndex":0,"ayuda":{"pista":"Cuando la pregunta dice CUÁNTO DURA o QUÉ DÍA, lo que se mide es tiempo.","pasos":["El tiempo corto —un juego, una clase— se mide con un reloj.","El tiempo largo —los días, las semanas— se mira en un calendario.","Ni la balanza ni la regla sirven: el tiempo no pesa ni tiene largo."],"ojo":"Un reloj y un calendario miden los dos el tiempo, pero uno corto y el otro largo."}}'::jsonb, 8);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('a4a04c77-67fa-4470-a795-f71adb915327'::uuid, 'multiple_choice', '¿Con qué sabes qué día es hoy?', '{"options":["Con un calendario","Con una regla","Con una balanza","Con un vaso"],"correctIndex":0,"ayuda":{"pista":"Cuando la pregunta dice CUÁNTO DURA o QUÉ DÍA, lo que se mide es tiempo.","pasos":["El tiempo corto —un juego, una clase— se mide con un reloj.","El tiempo largo —los días, las semanas— se mira en un calendario.","Ni la balanza ni la regla sirven: el tiempo no pesa ni tiene largo."],"ojo":"Un reloj y un calendario miden los dos el tiempo, pero uno corto y el otro largo."}}'::jsonb, 8);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('a4a04c77-67fa-4470-a795-f71adb915327'::uuid, 'multiple_choice', '¿Con qué sabes cuánta agua CABE en una jarra?', '{"options":["Con un vaso","Con una regla","Con un reloj","Con una balanza"],"correctIndex":0,"ayuda":{"pista":"Para saber cuánto CABE, se llena con algo más pequeño y se cuenta cuántos entraron.","pasos":["La capacidad se mide llenando: vasos para el agua, pocillos para el arroz.","Se cuenta cuántos vasos o pocillos entraron, y ese número es la medida.","Cuidado: si la pregunta cambia y pide el LARGO, entonces sí es una regla."],"ojo":"Una de estas tres preguntas no es de capacidad. Léela bien antes de contestar."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('a4a04c77-67fa-4470-a795-f71adb915327'::uuid, 'multiple_choice', '¿Con qué sabes cuánto arroz CABE en una olla?', '{"options":["Con un pocillo","Con una regla","Con un reloj","Con un metro"],"correctIndex":0,"ayuda":{"pista":"Para saber cuánto CABE, se llena con algo más pequeño y se cuenta cuántos entraron.","pasos":["La capacidad se mide llenando: vasos para el agua, pocillos para el arroz.","Se cuenta cuántos vasos o pocillos entraron, y ese número es la medida.","Cuidado: si la pregunta cambia y pide el LARGO, entonces sí es una regla."],"ojo":"Una de estas tres preguntas no es de capacidad. Léela bien antes de contestar."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('a4a04c77-67fa-4470-a795-f71adb915327'::uuid, 'multiple_choice', '¿Con qué mides el largo de un cuaderno?', '{"options":["Con una regla","Con un reloj","Con una balanza","Con un vaso"],"correctIndex":0,"ayuda":{"pista":"Para saber cuánto CABE, se llena con algo más pequeño y se cuenta cuántos entraron.","pasos":["La capacidad se mide llenando: vasos para el agua, pocillos para el arroz.","Se cuenta cuántos vasos o pocillos entraron, y ese número es la medida.","Cuidado: si la pregunta cambia y pide el LARGO, entonces sí es una regla."],"ojo":"Una de estas tres preguntas no es de capacidad. Léela bien antes de contestar."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('3d6f9e53-46d4-4f27-ab3c-3feea7faefd0'::uuid, 'multiple_choice', '¿Quién caminó MÁS?', '{"options":["El que dio 30 pasos","El que dio 20 pasos","El que dio 10 pasos","El que dio 5 pasos"],"correctIndex":0,"ayuda":{"pista":"Si los dos midieron con lo mismo, el que dio más pasos recorrió más.","pasos":["Cuando se mide con pasos o baldosas, el número dice cuánto se recorrió.","Como la unidad es la misma para todos, se pueden comparar los números directamente.","Más pasos es más camino; menos pasos es menos camino."],"ojo":"Esto solo vale si los pasos son iguales. Con pasos distintos, los números no se pueden comparar."}}'::jsonb, 10);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('3d6f9e53-46d4-4f27-ab3c-3feea7faefd0'::uuid, 'multiple_choice', '¿Quién caminó MENOS?', '{"options":["El que dio 8 pasos","El que dio 15 pasos","El que dio 22 pasos","El que dio 40 pasos"],"correctIndex":0,"ayuda":{"pista":"Si los dos midieron con lo mismo, el que dio más pasos recorrió más.","pasos":["Cuando se mide con pasos o baldosas, el número dice cuánto se recorrió.","Como la unidad es la misma para todos, se pueden comparar los números directamente.","Más pasos es más camino; menos pasos es menos camino."],"ojo":"Esto solo vale si los pasos son iguales. Con pasos distintos, los números no se pueden comparar."}}'::jsonb, 10);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('3d6f9e53-46d4-4f27-ab3c-3feea7faefd0'::uuid, 'multiple_choice', '¿Cuál recorrido es MÁS LARGO?', '{"options":["25 baldosas","18 baldosas","12 baldosas","6 baldosas"],"correctIndex":0,"ayuda":{"pista":"Si los dos midieron con lo mismo, el que dio más pasos recorrió más.","pasos":["Cuando se mide con pasos o baldosas, el número dice cuánto se recorrió.","Como la unidad es la misma para todos, se pueden comparar los números directamente.","Más pasos es más camino; menos pasos es menos camino."],"ojo":"Esto solo vale si los pasos son iguales. Con pasos distintos, los números no se pueden comparar."}}'::jsonb, 10);
insert into learning_evidences (id, dba_id, num, texto) select 'f21ffb3c-287f-420a-b572-2be7eeec79ed'::uuid, d.id, 1, 'Mide longitudes con diferentes instrumentos y expresa el resultado en unidades estandarizadas o no estandarizadas comunes.' from dbas d join subjects s on s.id = d.subject_id and s.slug = 'matematicas' where d.grade = 1 and d.num = 5;
