insert into learning_evidences (id, dba_id, num, texto) select '9b742362-5f58-4cac-ad32-5e2c15e69ac7'::uuid, d.id, 3, 'Toma decisiones a partir de las mediciones realizadas y de acuerdo con los requerimientos del problema.' from dbas d join subjects s on s.id = d.subject_id and s.slug = 'matematicas' where d.grade = 1 and d.num = 5;
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('f21ffb3c-287f-420a-b572-2be7eeec79ed'::uuid, 'multiple_choice', 'La mesa mide 4 cuartas. ¿Con qué la mediste?', '{"options":["Con la mano","Con un reloj","Con una balanza","Con un vaso"],"correctIndex":0,"ayuda":{"pista":"La medida te dice el instrumento: si dice cuartas, mediste con la mano.","pasos":["Para medir no siempre hace falta una regla: sirve la mano, el pie o cualquier objeto repetido.","Una cuarta es la mano abierta, del pulgar al meñique.","El nombre de la medida delata con qué se midió: pasos con los pies, clips con clips."],"ojo":"La unidad tiene que servir para lo que se mide: con un reloj no se mide una mesa."}}'::jsonb, 1);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('f21ffb3c-287f-420a-b572-2be7eeec79ed'::uuid, 'multiple_choice', 'El salón mide 12 pasos. ¿Con qué lo mediste?', '{"options":["Con los pies","Con un reloj","Con una balanza","Con un vaso"],"correctIndex":0,"ayuda":{"pista":"La medida te dice el instrumento: si dice cuartas, mediste con la mano.","pasos":["Para medir no siempre hace falta una regla: sirve la mano, el pie o cualquier objeto repetido.","Una cuarta es la mano abierta, del pulgar al meñique.","El nombre de la medida delata con qué se midió: pasos con los pies, clips con clips."],"ojo":"La unidad tiene que servir para lo que se mide: con un reloj no se mide una mesa."}}'::jsonb, 1);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('f21ffb3c-287f-420a-b572-2be7eeec79ed'::uuid, 'multiple_choice', 'El cuaderno mide 6 clips. ¿Con qué lo mediste?', '{"options":["Con clips","Con un reloj","Con una balanza","Con agua"],"correctIndex":0,"ayuda":{"pista":"La medida te dice el instrumento: si dice cuartas, mediste con la mano.","pasos":["Para medir no siempre hace falta una regla: sirve la mano, el pie o cualquier objeto repetido.","Una cuarta es la mano abierta, del pulgar al meñique.","El nombre de la medida delata con qué se midió: pasos con los pies, clips con clips."],"ojo":"La unidad tiene que servir para lo que se mide: con un reloj no se mide una mesa."}}'::jsonb, 1);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('b56f198a-ba7e-431e-a061-61325dddc74d'::uuid, 'multiple_choice', '¿Cuál dura MÁS?', '{"options":["Una clase","Un parpadeo","Un estornudo","Un aplauso"],"correctIndex":0,"ayuda":{"pista":"Piensa cuánto tarda cada cosa de verdad, y ordénalas de la más corta a la más larga.","pasos":["Ordena las opciones por su duración: un parpadeo, un aplauso, un recreo, una clase, un día.","Algunas son de un segundo y otras de horas: la diferencia es enorme.","Elige la punta que te piden, la que dura más o la que dura menos."],"ojo":"Lee si piden MÁS o MENOS. Aquí no siempre piden lo mismo."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('b56f198a-ba7e-431e-a061-61325dddc74d'::uuid, 'multiple_choice', '¿Cuál dura MÁS?', '{"options":["Un día","Una hora","Un minuto","Un segundo"],"correctIndex":0,"ayuda":{"pista":"Piensa cuánto tarda cada cosa de verdad, y ordénalas de la más corta a la más larga.","pasos":["Ordena las opciones por su duración: un parpadeo, un aplauso, un recreo, una clase, un día.","Algunas son de un segundo y otras de horas: la diferencia es enorme.","Elige la punta que te piden, la que dura más o la que dura menos."],"ojo":"Lee si piden MÁS o MENOS. Aquí no siempre piden lo mismo."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('b56f198a-ba7e-431e-a061-61325dddc74d'::uuid, 'multiple_choice', '¿Cuál dura MENOS?', '{"options":["Un salto","Un recreo","Una clase","Una semana"],"correctIndex":0,"ayuda":{"pista":"Piensa cuánto tarda cada cosa de verdad, y ordénalas de la más corta a la más larga.","pasos":["Ordena las opciones por su duración: un parpadeo, un aplauso, un recreo, una clase, un día.","Algunas son de un segundo y otras de horas: la diferencia es enorme.","Elige la punta que te piden, la que dura más o la que dura menos."],"ojo":"Lee si piden MÁS o MENOS. Aquí no siempre piden lo mismo."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('b56f198a-ba7e-431e-a061-61325dddc74d'::uuid, 'multiple_choice', '¿Cuál pesa MENOS?', '{"options":["Una pluma","Un libro","Un zapato","Una piedra"],"correctIndex":0,"ayuda":{"pista":"Imagina que cargas cada cosa. Ordénalas de la más liviana a la más pesada.","pasos":["Piensa en cada objeto con la mano: una pluma casi no se siente, una nevera no la levantas.","Ponlos en fila de mentiras, del más liviano al más pesado.","Elige la punta que te pide la pregunta."],"ojo":"Fíjate si piden el que MÁS pesa o el que MENOS pesa."}}'::jsonb, 3);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('b56f198a-ba7e-431e-a061-61325dddc74d'::uuid, 'multiple_choice', '¿Cuál pesa MENOS?', '{"options":["Un algodón","Una manzana","Un ladrillo","Una silla"],"correctIndex":0,"ayuda":{"pista":"Imagina que cargas cada cosa. Ordénalas de la más liviana a la más pesada.","pasos":["Piensa en cada objeto con la mano: una pluma casi no se siente, una nevera no la levantas.","Ponlos en fila de mentiras, del más liviano al más pesado.","Elige la punta que te pide la pregunta."],"ojo":"Fíjate si piden el que MÁS pesa o el que MENOS pesa."}}'::jsonb, 3);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('b56f198a-ba7e-431e-a061-61325dddc74d'::uuid, 'multiple_choice', '¿Cuál pesa MÁS?', '{"options":["Una nevera","Una silla","Un plato","Una cuchara"],"correctIndex":0,"ayuda":{"pista":"Imagina que cargas cada cosa. Ordénalas de la más liviana a la más pesada.","pasos":["Piensa en cada objeto con la mano: una pluma casi no se siente, una nevera no la levantas.","Ponlos en fila de mentiras, del más liviano al más pesado.","Elige la punta que te pide la pregunta."],"ojo":"Fíjate si piden el que MÁS pesa o el que MENOS pesa."}}'::jsonb, 3);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('b56f198a-ba7e-431e-a061-61325dddc74d'::uuid, 'multiple_choice', 'Las dos cintas miden lo mismo. Entonces son:', '{"options":["Igual de largas","La roja más larga","La azul más larga","No se pueden comparar"],"correctIndex":0,"visual":{"tipo":"barras","datos":[{"etiqueta":"Roja","valor":8},{"etiqueta":"Azul","valor":8}]},"ayuda":{"pista":"Mira las dos barras del dibujo: la más larga es la que mide más.","pasos":["Las dos cosas están medidas con la misma unidad, así que se pueden comparar.","Mira el dibujo: la barra más larga es la que mide más, y la más corta la que mide menos.","Si las dos barras llegan hasta el mismo punto, miden lo mismo."],"ojo":"Esto solo funciona porque las dos se midieron con lo MISMO."}}'::jsonb, 4);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('b56f198a-ba7e-431e-a061-61325dddc74d'::uuid, 'multiple_choice', '¿Cuál cinta es más larga? (medidas en clips)', '{"options":["La roja","La azul","Son iguales","No se sabe"],"correctIndex":0,"visual":{"tipo":"barras","datos":[{"etiqueta":"Roja","valor":9},{"etiqueta":"Azul","valor":6}]},"ayuda":{"pista":"Mira las dos barras del dibujo: la más larga es la que mide más.","pasos":["Las dos cosas están medidas con la misma unidad, así que se pueden comparar.","Mira el dibujo: la barra más larga es la que mide más, y la más corta la que mide menos.","Si las dos barras llegan hasta el mismo punto, miden lo mismo."],"ojo":"Esto solo funciona porque las dos se midieron con lo MISMO."}}'::jsonb, 4);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('b56f198a-ba7e-431e-a061-61325dddc74d'::uuid, 'multiple_choice', '¿Cuál cuerda es más corta? (medidas en cuartas)', '{"options":["La verde","La café","Son iguales","No se sabe"],"correctIndex":0,"visual":{"tipo":"barras","datos":[{"etiqueta":"Verde","valor":4},{"etiqueta":"Café","valor":7}]},"ayuda":{"pista":"Mira las dos barras del dibujo: la más larga es la que mide más.","pasos":["Las dos cosas están medidas con la misma unidad, así que se pueden comparar.","Mira el dibujo: la barra más larga es la que mide más, y la más corta la que mide menos.","Si las dos barras llegan hasta el mismo punto, miden lo mismo."],"ojo":"Esto solo funciona porque las dos se midieron con lo MISMO."}}'::jsonb, 4);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('b56f198a-ba7e-431e-a061-61325dddc74d'::uuid, 'multiple_choice', 'Cada jarra llenó estos vasos. ¿Cuál tiene MÁS agua?', '{"options":["La jarra B","La jarra A","Las dos igual","No se sabe"],"correctIndex":0,"visual":{"tipo":"barras","datos":[{"etiqueta":"Jarra A","valor":4},{"etiqueta":"Jarra B","valor":7}]},"ayuda":{"pista":"El que llenó más vasos es el que tiene más adentro.","pasos":["Para comparar cuánto le cabe a dos recipientes, se llenan los dos con lo mismo.","Se cuenta cuántos vasos o pocillos salieron de cada uno.","El que dio más vasos es el que tenía más, aunque por fuera parezca más pequeño."],"ojo":"No se compara por el tamaño de afuera: se compara por lo que le cupo."}}'::jsonb, 5);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('b56f198a-ba7e-431e-a061-61325dddc74d'::uuid, 'multiple_choice', 'Cada balde llenó estos vasos. ¿Cuál tiene MENOS agua?', '{"options":["El balde A","El balde B","Los dos igual","No se sabe"],"correctIndex":0,"visual":{"tipo":"barras","datos":[{"etiqueta":"Balde A","valor":3},{"etiqueta":"Balde B","valor":9}]},"ayuda":{"pista":"El que llenó más vasos es el que tiene más adentro.","pasos":["Para comparar cuánto le cabe a dos recipientes, se llenan los dos con lo mismo.","Se cuenta cuántos vasos o pocillos salieron de cada uno.","El que dio más vasos es el que tenía más, aunque por fuera parezca más pequeño."],"ojo":"No se compara por el tamaño de afuera: se compara por lo que le cupo."}}'::jsonb, 5);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('b56f198a-ba7e-431e-a061-61325dddc74d'::uuid, 'multiple_choice', 'Cada olla lleva estos pocillos. ¿Cuál es más grande?', '{"options":["La olla B","La olla A","Las dos igual","No se sabe"],"correctIndex":0,"visual":{"tipo":"barras","datos":[{"etiqueta":"Olla A","valor":6},{"etiqueta":"Olla B","valor":10}]},"ayuda":{"pista":"El que llenó más vasos es el que tiene más adentro.","pasos":["Para comparar cuánto le cabe a dos recipientes, se llenan los dos con lo mismo.","Se cuenta cuántos vasos o pocillos salieron de cada uno.","El que dio más vasos es el que tenía más, aunque por fuera parezca más pequeño."],"ojo":"No se compara por el tamaño de afuera: se compara por lo que le cupo."}}'::jsonb, 5);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('f21ffb3c-287f-420a-b572-2be7eeec79ed'::uuid, 'multiple_choice', '¿Cuántos clips más largo es el lápiz azul?', '{"options":["2","8","1","3"],"correctIndex":0,"visual":{"tipo":"barras","datos":[{"etiqueta":"Rojo","valor":3},{"etiqueta":"Azul","valor":5}]},"ayuda":{"pista":"Para saber cuánto MÁS mide uno que otro, se resta la medida pequeña de la grande.","pasos":["Mira las dos barras y fíjate cuál es la más larga.","La pregunta es cuánto le sobra a esa por encima de la otra.","Eso se averigua restando: la medida grande menos la pequeña."],"ojo":"Aquí no se suman las dos medidas. Se busca la diferencia entre ellas."}}'::jsonb, 6);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('f21ffb3c-287f-420a-b572-2be7eeec79ed'::uuid, 'multiple_choice', '¿Cuántos clips más larga es la cinta verde?', '{"options":["5","13","4","6"],"correctIndex":0,"visual":{"tipo":"barras","datos":[{"etiqueta":"Café","valor":4},{"etiqueta":"Verde","valor":9}]},"ayuda":{"pista":"Para saber cuánto MÁS mide uno que otro, se resta la medida pequeña de la grande.","pasos":["Mira las dos barras y fíjate cuál es la más larga.","La pregunta es cuánto le sobra a esa por encima de la otra.","Eso se averigua restando: la medida grande menos la pequeña."],"ojo":"Aquí no se suman las dos medidas. Se busca la diferencia entre ellas."}}'::jsonb, 6);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('f21ffb3c-287f-420a-b572-2be7eeec79ed'::uuid, 'multiple_choice', '¿Cuántas cuartas más larga es la mesa grande?', '{"options":["3","13","2","4"],"correctIndex":0,"visual":{"tipo":"barras","datos":[{"etiqueta":"Chica","valor":5},{"etiqueta":"Grande","valor":8}]},"ayuda":{"pista":"Para saber cuánto MÁS mide uno que otro, se resta la medida pequeña de la grande.","pasos":["Mira las dos barras y fíjate cuál es la más larga.","La pregunta es cuánto le sobra a esa por encima de la otra.","Eso se averigua restando: la medida grande menos la pequeña."],"ojo":"Aquí no se suman las dos medidas. Se busca la diferencia entre ellas."}}'::jsonb, 6);
