insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('9b742362-5f58-4cac-ad32-5e2c15e69ac7'::uuid, 'multiple_choice', 'Tienes 15 palitos y usas 6.', '{"options":["9","21","8","10"],"correctIndex":0,"operation":"15 − 6 = ?"}'::jsonb, 8);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('9b742362-5f58-4cac-ad32-5e2c15e69ac7'::uuid, 'multiple_choice', 'Mide en cuartas. ¿Cabe la caja en el estante?', '{"options":["No, la caja es más grande","Sí, y sobra espacio","Sí, entra justo","No se sabe"],"correctIndex":0,"visual":{"tipo":"barras","datos":[{"etiqueta":"Estante","valor":6},{"etiqueta":"Caja","valor":8}]},"ayuda":{"pista":"Compara las dos medidas: si lo que entra mide más que el espacio, no cabe.","pasos":["Mira cuánto mide el espacio y cuánto mide la cosa que quieres meter.","Si la cosa mide menos, cabe y además sobra.","Si mide más, no cabe. Y si miden exactamente igual, entra justo, sin sobrar nada."],"ojo":"Hay tres respuestas posibles, no dos: cabe con espacio, entra justo, o no cabe."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('9b742362-5f58-4cac-ad32-5e2c15e69ac7'::uuid, 'multiple_choice', 'Mide en cuartas. ¿Cabe el libro en la maleta?', '{"options":["Sí, y sobra espacio","No, el libro es más grande","Entra justo","No se sabe"],"correctIndex":0,"visual":{"tipo":"barras","datos":[{"etiqueta":"Maleta","valor":9},{"etiqueta":"Libro","valor":4}]},"ayuda":{"pista":"Compara las dos medidas: si lo que entra mide más que el espacio, no cabe.","pasos":["Mira cuánto mide el espacio y cuánto mide la cosa que quieres meter.","Si la cosa mide menos, cabe y además sobra.","Si mide más, no cabe. Y si miden exactamente igual, entra justo, sin sobrar nada."],"ojo":"Hay tres respuestas posibles, no dos: cabe con espacio, entra justo, o no cabe."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('9b742362-5f58-4cac-ad32-5e2c15e69ac7'::uuid, 'multiple_choice', 'Mide en clips. ¿Alcanza la cinta para el regalo?', '{"options":["Sí, alcanza justo","No, falta cinta","Sobra mucha cinta","No se sabe"],"correctIndex":0,"visual":{"tipo":"barras","datos":[{"etiqueta":"Cinta","valor":7},{"etiqueta":"Regalo","valor":7}]},"ayuda":{"pista":"Compara las dos medidas: si lo que entra mide más que el espacio, no cabe.","pasos":["Mira cuánto mide el espacio y cuánto mide la cosa que quieres meter.","Si la cosa mide menos, cabe y además sobra.","Si mide más, no cabe. Y si miden exactamente igual, entra justo, sin sobrar nada."],"ojo":"Hay tres respuestas posibles, no dos: cabe con espacio, entra justo, o no cabe."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('f21ffb3c-287f-420a-b572-2be7eeec79ed'::uuid, 'multiple_choice', 'Si mides el salón con pasos GRANDES, das:', '{"options":["Menos pasos","Más pasos","Los mismos pasos","Ningún paso"],"correctIndex":0,"ayuda":{"pista":"Piensa: con una unidad más grande hacen falta menos veces para cubrir lo mismo.","pasos":["El objeto no cambia de tamaño: lo que cambia es con qué lo mides.","Si la unidad es grande —pasos largos, cuartas grandes— necesitas pocas para cubrirlo.","Si la unidad es pequeña —clips, pasos cortos— necesitas muchas más."],"ojo":"Es al revés de lo que parece: unidad más grande, número más pequeño."}}'::jsonb, 10);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('f21ffb3c-287f-420a-b572-2be7eeec79ed'::uuid, 'multiple_choice', 'Si mides la mesa con clips PEQUEÑOS, usas:', '{"options":["Más clips","Menos clips","Los mismos clips","Ningún clip"],"correctIndex":0,"ayuda":{"pista":"Piensa: con una unidad más grande hacen falta menos veces para cubrir lo mismo.","pasos":["El objeto no cambia de tamaño: lo que cambia es con qué lo mides.","Si la unidad es grande —pasos largos, cuartas grandes— necesitas pocas para cubrirlo.","Si la unidad es pequeña —clips, pasos cortos— necesitas muchas más."],"ojo":"Es al revés de lo que parece: unidad más grande, número más pequeño."}}'::jsonb, 10);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('f21ffb3c-287f-420a-b572-2be7eeec79ed'::uuid, 'multiple_choice', 'Si mides con una cuarta más grande, el número sale:', '{"options":["Más pequeño","Más grande","Igual","En cero"],"correctIndex":0,"ayuda":{"pista":"Piensa: con una unidad más grande hacen falta menos veces para cubrir lo mismo.","pasos":["El objeto no cambia de tamaño: lo que cambia es con qué lo mides.","Si la unidad es grande —pasos largos, cuartas grandes— necesitas pocas para cubrirlo.","Si la unidad es pequeña —clips, pasos cortos— necesitas muchas más."],"ojo":"Es al revés de lo que parece: unidad más grande, número más pequeño."}}'::jsonb, 10);
insert into learning_evidences (id, dba_id, num, texto) select '7aef2a84-ac01-4217-a998-e55cb056325e'::uuid, d.id, 1, 'Crea, compone y descompone formas bidimensionales y tridimensionales, para ello utiliza plastilina, papel, palitos, cajas, etc.' from dbas d join subjects s on s.id = d.subject_id and s.slug = 'matematicas' where d.grade = 1 and d.num = 6;
