insert into learning_evidences (id, dba_id, num, texto) select '14fe0ef9-9290-4e39-a71f-2cfb2e8a9d14'::uuid, d.id, 3, 'Agrupa objetos de su entorno de acuerdo con las semejanzas y las diferencias en la forma y en el tamaño y explica el criterio que utiliza.' from dbas d join subjects s on s.id = d.subject_id and s.slug = 'matematicas' where d.grade = 1 and d.num = 6;
insert into learning_evidences (id, dba_id, num, texto) select '9dda505d-4724-484c-a04f-2c9a61c8f24e'::uuid, d.id, 4, 'Identifica objetos a partir de las descripciones verbales que hacen de sus características geométricas.' from dbas d join subjects s on s.id = d.subject_id and s.slug = 'matematicas' where d.grade = 1 and d.num = 6;
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('17283077-8fee-439b-9d32-ba6c34e73f42'::uuid, 'multiple_choice', '¿Cuántos lados tiene un triángulo?', '{"options":["3","4","5","1"],"correctIndex":0,"ayuda":{"pista":"Cuenta los lados de la figura tocándolos con el dedo, uno por uno, dando la vuelta.","pasos":["Un lado es cada rayita recta que forma la figura.","Cuéntalos dando la vuelta completa y sin repetir ninguno.","El triángulo tiene 3 y el rectángulo tiene 4."],"ojo":"En estas figuras hay tantas puntas como lados: si cuentas 3 lados, hay 3 puntas."}}'::jsonb, 1);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('17283077-8fee-439b-9d32-ba6c34e73f42'::uuid, 'multiple_choice', '¿Cuántas puntas tiene un triángulo?', '{"options":["3","4","2","6"],"correctIndex":0,"ayuda":{"pista":"Cuenta los lados de la figura tocándolos con el dedo, uno por uno, dando la vuelta.","pasos":["Un lado es cada rayita recta que forma la figura.","Cuéntalos dando la vuelta completa y sin repetir ninguno.","El triángulo tiene 3 y el rectángulo tiene 4."],"ojo":"En estas figuras hay tantas puntas como lados: si cuentas 3 lados, hay 3 puntas."}}'::jsonb, 1);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('17283077-8fee-439b-9d32-ba6c34e73f42'::uuid, 'multiple_choice', '¿Cuántos lados tiene un rectángulo?', '{"options":["4","3","5","6"],"correctIndex":0,"ayuda":{"pista":"Cuenta los lados de la figura tocándolos con el dedo, uno por uno, dando la vuelta.","pasos":["Un lado es cada rayita recta que forma la figura.","Cuéntalos dando la vuelta completa y sin repetir ninguno.","El triángulo tiene 3 y el rectángulo tiene 4."],"ojo":"En estas figuras hay tantas puntas como lados: si cuentas 3 lados, hay 3 puntas."}}'::jsonb, 1);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('7aef2a84-ac01-4217-a998-e55cb056325e'::uuid, 'multiple_choice', '¿Con cuántos palitos haces un triángulo?', '{"options":["3","2","4","6"],"correctIndex":0,"ayuda":{"pista":"Cada palito es un lado. Cuenta cuántos lados necesita la figura.","pasos":["Para armar una figura con palitos, necesitas un palito por cada lado.","El triángulo tiene 3 lados: 3 palitos. El cuadrado tiene 4: 4 palitos.","Y si juntas dos cuadrados iguales uno al lado del otro, queda una figura más larga que alta: un rectángulo."],"ojo":"Con menos palitos que lados la figura no cierra, y una figura abierta no es una figura."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('7aef2a84-ac01-4217-a998-e55cb056325e'::uuid, 'multiple_choice', '¿Con cuántos palitos haces un cuadrado?', '{"options":["4","3","5","8"],"correctIndex":0,"ayuda":{"pista":"Cada palito es un lado. Cuenta cuántos lados necesita la figura.","pasos":["Para armar una figura con palitos, necesitas un palito por cada lado.","El triángulo tiene 3 lados: 3 palitos. El cuadrado tiene 4: 4 palitos.","Y si juntas dos cuadrados iguales uno al lado del otro, queda una figura más larga que alta: un rectángulo."],"ojo":"Con menos palitos que lados la figura no cierra, y una figura abierta no es una figura."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('7aef2a84-ac01-4217-a998-e55cb056325e'::uuid, 'multiple_choice', 'Con 2 cuadrados iguales, uno al lado del otro, armas un:', '{"options":["Rectángulo","Círculo","Triángulo","Cubo"],"correctIndex":0,"ayuda":{"pista":"Cada palito es un lado. Cuenta cuántos lados necesita la figura.","pasos":["Para armar una figura con palitos, necesitas un palito por cada lado.","El triángulo tiene 3 lados: 3 palitos. El cuadrado tiene 4: 4 palitos.","Y si juntas dos cuadrados iguales uno al lado del otro, queda una figura más larga que alta: un rectángulo."],"ojo":"Con menos palitos que lados la figura no cierra, y una figura abierta no es una figura."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('17283077-8fee-439b-9d32-ba6c34e73f42'::uuid, 'multiple_choice', '¿Cuántos lados tiene un cuadrado?', '{"options":["4","3","5","6"],"correctIndex":0,"ayuda":{"pista":"Cuenta tocando con el dedo. Y fíjate si la figura tiene rayitas rectas o no tiene ninguna.","pasos":["El cuadrado tiene 4 lados iguales y 4 esquinas, una en cada punta.","En estas figuras siempre hay tantas esquinas como lados.","El círculo es distinto: es una sola línea curva, sin lados rectos y sin esquinas."],"ojo":"El círculo no tiene 1 lado: no tiene ninguno, porque un lado es una rayita recta."}}'::jsonb, 3);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('17283077-8fee-439b-9d32-ba6c34e73f42'::uuid, 'multiple_choice', '¿Cuántas esquinas tiene un cuadrado?', '{"options":["4","3","5","2"],"correctIndex":0,"ayuda":{"pista":"Cuenta tocando con el dedo. Y fíjate si la figura tiene rayitas rectas o no tiene ninguna.","pasos":["El cuadrado tiene 4 lados iguales y 4 esquinas, una en cada punta.","En estas figuras siempre hay tantas esquinas como lados.","El círculo es distinto: es una sola línea curva, sin lados rectos y sin esquinas."],"ojo":"El círculo no tiene 1 lado: no tiene ninguno, porque un lado es una rayita recta."}}'::jsonb, 3);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('17283077-8fee-439b-9d32-ba6c34e73f42'::uuid, 'multiple_choice', '¿Cuántos lados tiene un círculo?', '{"options":["Ninguno","1","2","4"],"correctIndex":0,"ayuda":{"pista":"Cuenta tocando con el dedo. Y fíjate si la figura tiene rayitas rectas o no tiene ninguna.","pasos":["El cuadrado tiene 4 lados iguales y 4 esquinas, una en cada punta.","En estas figuras siempre hay tantas esquinas como lados.","El círculo es distinto: es una sola línea curva, sin lados rectos y sin esquinas."],"ojo":"El círculo no tiene 1 lado: no tiene ninguno, porque un lado es una rayita recta."}}'::jsonb, 3);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('9dda505d-4724-484c-a04f-2c9a61c8f24e'::uuid, 'multiple_choice', '¿Cuál figura es redonda?', '{"options":["Círculo","Triángulo","Cuadrado","Rectángulo"],"correctIndex":0,"ayuda":{"pista":"Lee qué característica piden —redonda, sin esquinas, más lados— y búscala en cada figura.","pasos":["Cada figura se reconoce por lo que tiene: lados, esquinas, si es curva o recta.","El círculo es el único que es curvo: no tiene lados ni esquinas.","El triángulo tiene 3 lados y el cuadrado 4, así que el cuadrado tiene más."],"ojo":"Fíjate si la pregunta tiene un NO. «Cuál NO tiene esquinas» pide lo contrario."}}'::jsonb, 4);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('9dda505d-4724-484c-a04f-2c9a61c8f24e'::uuid, 'multiple_choice', '¿Cuál figura NO tiene esquinas?', '{"options":["Círculo","Triángulo","Cuadrado","Rectángulo"],"correctIndex":0,"ayuda":{"pista":"Lee qué característica piden —redonda, sin esquinas, más lados— y búscala en cada figura.","pasos":["Cada figura se reconoce por lo que tiene: lados, esquinas, si es curva o recta.","El círculo es el único que es curvo: no tiene lados ni esquinas.","El triángulo tiene 3 lados y el cuadrado 4, así que el cuadrado tiene más."],"ojo":"Fíjate si la pregunta tiene un NO. «Cuál NO tiene esquinas» pide lo contrario."}}'::jsonb, 4);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('9dda505d-4724-484c-a04f-2c9a61c8f24e'::uuid, 'multiple_choice', '¿Cuál figura tiene más lados?', '{"options":["Cuadrado","Triángulo","Círculo","Todas igual"],"correctIndex":0,"ayuda":{"pista":"Lee qué característica piden —redonda, sin esquinas, más lados— y búscala en cada figura.","pasos":["Cada figura se reconoce por lo que tiene: lados, esquinas, si es curva o recta.","El círculo es el único que es curvo: no tiene lados ni esquinas.","El triángulo tiene 3 lados y el cuadrado 4, así que el cuadrado tiene más."],"ojo":"Fíjate si la pregunta tiene un NO. «Cuál NO tiene esquinas» pide lo contrario."}}'::jsonb, 4);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('9dda505d-4724-484c-a04f-2c9a61c8f24e'::uuid, 'multiple_choice', 'Tiene 3 lados y 3 puntas. Es un:', '{"options":["Triángulo","Cuadrado","Círculo","Rectángulo"],"correctIndex":0,"ayuda":{"pista":"Cuenta los lados que menciona la descripción y busca la figura que los tenga.","pasos":["La descripción te da las pistas: cuántos lados, cuántas puntas, si son rectos o curvos.","3 lados y 3 puntas solo lo cumple el triángulo.","4 lados con dos más largos es el rectángulo; sin lados rectos ni puntas, el círculo."],"ojo":"El cuadrado y el rectángulo tienen los dos 4 lados. Los diferencia si son todos iguales o no."}}'::jsonb, 5);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('9dda505d-4724-484c-a04f-2c9a61c8f24e'::uuid, 'multiple_choice', 'Tiene 4 lados y 2 son más largos. Es un:', '{"options":["Rectángulo","Triángulo","Círculo","Cuadrado"],"correctIndex":0,"ayuda":{"pista":"Cuenta los lados que menciona la descripción y busca la figura que los tenga.","pasos":["La descripción te da las pistas: cuántos lados, cuántas puntas, si son rectos o curvos.","3 lados y 3 puntas solo lo cumple el triángulo.","4 lados con dos más largos es el rectángulo; sin lados rectos ni puntas, el círculo."],"ojo":"El cuadrado y el rectángulo tienen los dos 4 lados. Los diferencia si son todos iguales o no."}}'::jsonb, 5);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('9dda505d-4724-484c-a04f-2c9a61c8f24e'::uuid, 'multiple_choice', 'No tiene lados rectos ni puntas. Es un:', '{"options":["Círculo","Triángulo","Cuadrado","Rectángulo"],"correctIndex":0,"ayuda":{"pista":"Cuenta los lados que menciona la descripción y busca la figura que los tenga.","pasos":["La descripción te da las pistas: cuántos lados, cuántas puntas, si son rectos o curvos.","3 lados y 3 puntas solo lo cumple el triángulo.","4 lados con dos más largos es el rectángulo; sin lados rectos ni puntas, el círculo."],"ojo":"El cuadrado y el rectángulo tienen los dos 4 lados. Los diferencia si son todos iguales o no."}}'::jsonb, 5);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('9dda505d-4724-484c-a04f-2c9a61c8f24e'::uuid, 'multiple_choice', 'Tiene 4 lados iguales y 4 puntas. Es un:', '{"options":["Cuadrado","Rectángulo","Triángulo","Círculo"],"correctIndex":0,"ayuda":{"pista":"La descripción dice cuántos lados y cómo son. Eso alcanza para saber cuál es.","pasos":["4 lados IGUALES es el cuadrado; si dos son más largos, es el rectángulo.","3 lados iguales es el triángulo.","Y lo que rueda y no tiene puntas es el círculo, porque es todo curvo."],"ojo":"La palabra «iguales» es la que decide entre cuadrado y rectángulo."}}'::jsonb, 6);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('9dda505d-4724-484c-a04f-2c9a61c8f24e'::uuid, 'multiple_choice', 'Rueda y no tiene puntas. Es un:', '{"options":["Círculo","Cuadrado","Triángulo","Rectángulo"],"correctIndex":0,"ayuda":{"pista":"La descripción dice cuántos lados y cómo son. Eso alcanza para saber cuál es.","pasos":["4 lados IGUALES es el cuadrado; si dos son más largos, es el rectángulo.","3 lados iguales es el triángulo.","Y lo que rueda y no tiene puntas es el círculo, porque es todo curvo."],"ojo":"La palabra «iguales» es la que decide entre cuadrado y rectángulo."}}'::jsonb, 6);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('9dda505d-4724-484c-a04f-2c9a61c8f24e'::uuid, 'multiple_choice', 'Tiene 3 lados iguales. Es un:', '{"options":["Triángulo","Cuadrado","Círculo","Rectángulo"],"correctIndex":0,"ayuda":{"pista":"La descripción dice cuántos lados y cómo son. Eso alcanza para saber cuál es.","pasos":["4 lados IGUALES es el cuadrado; si dos son más largos, es el rectángulo.","3 lados iguales es el triángulo.","Y lo que rueda y no tiene puntas es el círculo, porque es todo curvo."],"ojo":"La palabra «iguales» es la que decide entre cuadrado y rectángulo."}}'::jsonb, 6);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('17283077-8fee-439b-9d32-ba6c34e73f42'::uuid, 'multiple_choice', '¿Cuál de estas cosas tiene el borde CURVO?', '{"options":["Un plato","Una regla","Una mesa","Un libro"],"correctIndex":0,"ayuda":{"pista":"Pasa el dedo por el borde de mentiras: si da la vuelta sin frenar, es curvo.","pasos":["Un borde curvo se sigue con el dedo sin tropezar con ninguna esquina.","Un borde recto va derecho y se frena en una esquina.","Los platos, las monedas y los anillos son curvos; las reglas, los libros y las mesas son rectos."],"ojo":"Mírale el borde, no el tamaño ni para qué sirve el objeto."}}'::jsonb, 7);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('17283077-8fee-439b-9d32-ba6c34e73f42'::uuid, 'multiple_choice', '¿Cuál de estas cosas tiene el borde RECTO?', '{"options":["Una regla","Un plato","Una moneda","Un anillo"],"correctIndex":0,"ayuda":{"pista":"Pasa el dedo por el borde de mentiras: si da la vuelta sin frenar, es curvo.","pasos":["Un borde curvo se sigue con el dedo sin tropezar con ninguna esquina.","Un borde recto va derecho y se frena en una esquina.","Los platos, las monedas y los anillos son curvos; las reglas, los libros y las mesas son rectos."],"ojo":"Mírale el borde, no el tamaño ni para qué sirve el objeto."}}'::jsonb, 7);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('17283077-8fee-439b-9d32-ba6c34e73f42'::uuid, 'multiple_choice', '¿Cuál de estas cosas es redonda?', '{"options":["Una moneda","Un libro","Una caja","Una puerta"],"correctIndex":0,"ayuda":{"pista":"Pasa el dedo por el borde de mentiras: si da la vuelta sin frenar, es curvo.","pasos":["Un borde curvo se sigue con el dedo sin tropezar con ninguna esquina.","Un borde recto va derecho y se frena en una esquina.","Los platos, las monedas y los anillos son curvos; las reglas, los libros y las mesas son rectos."],"ojo":"Mírale el borde, no el tamaño ni para qué sirve el objeto."}}'::jsonb, 7);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('14fe0ef9-9290-4e39-a71f-2cfb2e8a9d14'::uuid, 'multiple_choice', 'Una pelota tiene forma de:', '{"options":["Esfera","Cubo","Cilindro","Pirámide"],"correctIndex":0,"ayuda":{"pista":"Piensa si el objeto rueda para todos lados o si tiene caras planas.","pasos":["La esfera es redonda por todas partes y rueda para cualquier lado: una pelota, una naranja.","El cubo tiene caras planas y no rueda.","Cuidado con la Luna: en el cielo se VE como un círculo plano, aunque de verdad sea una esfera."],"ojo":"El círculo es plano, como un dibujo. La esfera es un cuerpo que se puede agarrar."}}'::jsonb, 8);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('14fe0ef9-9290-4e39-a71f-2cfb2e8a9d14'::uuid, 'multiple_choice', 'Una naranja tiene forma de:', '{"options":["Esfera","Cubo","Cono","Cilindro"],"correctIndex":0,"ayuda":{"pista":"Piensa si el objeto rueda para todos lados o si tiene caras planas.","pasos":["La esfera es redonda por todas partes y rueda para cualquier lado: una pelota, una naranja.","El cubo tiene caras planas y no rueda.","Cuidado con la Luna: en el cielo se VE como un círculo plano, aunque de verdad sea una esfera."],"ojo":"El círculo es plano, como un dibujo. La esfera es un cuerpo que se puede agarrar."}}'::jsonb, 8);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('14fe0ef9-9290-4e39-a71f-2cfb2e8a9d14'::uuid, 'multiple_choice', 'La Luna se ve con forma de:', '{"options":["Círculo","Cuadrado","Triángulo","Rectángulo"],"correctIndex":0,"ayuda":{"pista":"Piensa si el objeto rueda para todos lados o si tiene caras planas.","pasos":["La esfera es redonda por todas partes y rueda para cualquier lado: una pelota, una naranja.","El cubo tiene caras planas y no rueda.","Cuidado con la Luna: en el cielo se VE como un círculo plano, aunque de verdad sea una esfera."],"ojo":"El círculo es plano, como un dibujo. La esfera es un cuerpo que se puede agarrar."}}'::jsonb, 8);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('14fe0ef9-9290-4e39-a71f-2cfb2e8a9d14'::uuid, 'multiple_choice', 'Un dado tiene forma de:', '{"options":["Cubo","Esfera","Cono","Cilindro"],"correctIndex":0,"ayuda":{"pista":"Cuéntale las caras de mentiras: ¿son todas cuadradas, o unas más largas?","pasos":["El cubo tiene 6 caras cuadradas, todas iguales: por eso un dado es un cubo.","El prisma también tiene 6 caras, pero unas más largas que otras: una caja de zapatos.","El cono tiene una punta arriba y una base redonda: un gorro de cumpleaños."],"ojo":"El cubo y el prisma se parecen. Lo que los distingue es si todas las caras son iguales."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('14fe0ef9-9290-4e39-a71f-2cfb2e8a9d14'::uuid, 'multiple_choice', 'Una caja de zapatos tiene forma de:', '{"options":["Prisma","Esfera","Cono","Cilindro"],"correctIndex":0,"ayuda":{"pista":"Cuéntale las caras de mentiras: ¿son todas cuadradas, o unas más largas?","pasos":["El cubo tiene 6 caras cuadradas, todas iguales: por eso un dado es un cubo.","El prisma también tiene 6 caras, pero unas más largas que otras: una caja de zapatos.","El cono tiene una punta arriba y una base redonda: un gorro de cumpleaños."],"ojo":"El cubo y el prisma se parecen. Lo que los distingue es si todas las caras son iguales."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('14fe0ef9-9290-4e39-a71f-2cfb2e8a9d14'::uuid, 'multiple_choice', 'Un gorro de cumpleaños tiene forma de:', '{"options":["Cono","Cubo","Esfera","Cilindro"],"correctIndex":0,"ayuda":{"pista":"Cuéntale las caras de mentiras: ¿son todas cuadradas, o unas más largas?","pasos":["El cubo tiene 6 caras cuadradas, todas iguales: por eso un dado es un cubo.","El prisma también tiene 6 caras, pero unas más largas que otras: una caja de zapatos.","El cono tiene una punta arriba y una base redonda: un gorro de cumpleaños."],"ojo":"El cubo y el prisma se parecen. Lo que los distingue es si todas las caras son iguales."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('14fe0ef9-9290-4e39-a71f-2cfb2e8a9d14'::uuid, 'multiple_choice', 'Una caja de galletas tiene forma de:', '{"options":["Prisma","Cilindro","Esfera","Cono"],"correctIndex":0,"ayuda":{"pista":"Si tiene dos tapas redondas y rueda como un rodillo, es un cilindro.","pasos":["El cilindro tiene dos tapas redondas iguales y un tubo entre las dos: una lata, un rollo de papel.","Rueda, pero solo para un lado, no como una pelota.","La caja de galletas es distinta: tiene caras planas y esquinas, así que es un prisma."],"ojo":"Aquí no todos son cilindros. Míralo bien antes de contestar."}}'::jsonb, 10);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('14fe0ef9-9290-4e39-a71f-2cfb2e8a9d14'::uuid, 'multiple_choice', 'Una lata de gaseosa tiene forma de:', '{"options":["Cilindro","Cubo","Esfera","Cono"],"correctIndex":0,"ayuda":{"pista":"Si tiene dos tapas redondas y rueda como un rodillo, es un cilindro.","pasos":["El cilindro tiene dos tapas redondas iguales y un tubo entre las dos: una lata, un rollo de papel.","Rueda, pero solo para un lado, no como una pelota.","La caja de galletas es distinta: tiene caras planas y esquinas, así que es un prisma."],"ojo":"Aquí no todos son cilindros. Míralo bien antes de contestar."}}'::jsonb, 10);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('14fe0ef9-9290-4e39-a71f-2cfb2e8a9d14'::uuid, 'multiple_choice', 'Un rollo de papel tiene forma de:', '{"options":["Cilindro","Cubo","Esfera","Pirámide"],"correctIndex":0,"ayuda":{"pista":"Si tiene dos tapas redondas y rueda como un rodillo, es un cilindro.","pasos":["El cilindro tiene dos tapas redondas iguales y un tubo entre las dos: una lata, un rollo de papel.","Rueda, pero solo para un lado, no como una pelota.","La caja de galletas es distinta: tiene caras planas y esquinas, así que es un prisma."],"ojo":"Aquí no todos son cilindros. Míralo bien antes de contestar."}}'::jsonb, 10);
