insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('229976ae-e697-457e-8de9-be5d691067cd'::uuid, 'multiple_choice', 'El perro está DEBAJO de la mesa. Entonces la mesa está:', '{"options":["Encima del perro","Debajo del perro","Al lado del perro","Lejos del perro"],"correctIndex":0,"ayuda":{"pista":"Ponte en el lugar del otro objeto: lo que está debajo de algo tiene ese algo encima.","pasos":["Estar encima y estar debajo son la misma situación vista desde los dos lados.","Si el perro está debajo de la mesa, desde el perro la mesa se ve arriba.","Lo mismo con dentro: si el gato está dentro de la caja, la caja lo rodea por todos lados."],"ojo":"Si los dos estuvieran debajo del otro, alguno tendría que estar en dos sitios a la vez."}}'::jsonb, 1);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('229976ae-e697-457e-8de9-be5d691067cd'::uuid, 'multiple_choice', 'El libro está ENCIMA del cuaderno. El cuaderno está:', '{"options":["Debajo del libro","Encima del libro","Al lado del libro","Lejos del libro"],"correctIndex":0,"ayuda":{"pista":"Ponte en el lugar del otro objeto: lo que está debajo de algo tiene ese algo encima.","pasos":["Estar encima y estar debajo son la misma situación vista desde los dos lados.","Si el perro está debajo de la mesa, desde el perro la mesa se ve arriba.","Lo mismo con dentro: si el gato está dentro de la caja, la caja lo rodea por todos lados."],"ojo":"Si los dos estuvieran debajo del otro, alguno tendría que estar en dos sitios a la vez."}}'::jsonb, 1);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('229976ae-e697-457e-8de9-be5d691067cd'::uuid, 'multiple_choice', 'El gato está DENTRO de la caja. La caja está:', '{"options":["Alrededor del gato","Dentro del gato","Debajo del gato","Lejos del gato"],"correctIndex":0,"ayuda":{"pista":"Ponte en el lugar del otro objeto: lo que está debajo de algo tiene ese algo encima.","pasos":["Estar encima y estar debajo son la misma situación vista desde los dos lados.","Si el perro está debajo de la mesa, desde el perro la mesa se ve arriba.","Lo mismo con dentro: si el gato está dentro de la caja, la caja lo rodea por todos lados."],"ojo":"Si los dos estuvieran debajo del otro, alguno tendría que estar en dos sitios a la vez."}}'::jsonb, 1);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('7fa40b84-9fad-4b2c-a2c4-faa1a3bb5d44'::uuid, 'multiple_choice', 'En el plano, ¿cuál camino al parque es MÁS LARGO?', '{"options":["Por la tienda","Derecho","Miden igual","No se sabe"],"correctIndex":0,"visual":{"tipo":"barras","datos":[{"etiqueta":"Por la tienda","valor":30},{"etiqueta":"Derecho","valor":12}]},"ayuda":{"pista":"Los dos caminos están medidos con lo mismo. Compara los dos números.","pasos":["Mira las dos barras del dibujo: cada una es un camino.","La barra más larga es el camino más largo, y la más corta el camino más corto.","Si las dos miden igual, da lo mismo por dónde te vayas."],"ojo":"Lee si piden el MÁS largo o el MÁS corto: es lo único que cambia."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('7fa40b84-9fad-4b2c-a2c4-faa1a3bb5d44'::uuid, 'multiple_choice', 'En el plano, ¿cuál camino al colegio es MÁS CORTO?', '{"options":["Por el puente","Por la loma","Miden igual","No se sabe"],"correctIndex":0,"visual":{"tipo":"barras","datos":[{"etiqueta":"Por el puente","valor":6},{"etiqueta":"Por la loma","valor":14}]},"ayuda":{"pista":"Los dos caminos están medidos con lo mismo. Compara los dos números.","pasos":["Mira las dos barras del dibujo: cada una es un camino.","La barra más larga es el camino más largo, y la más corta el camino más corto.","Si las dos miden igual, da lo mismo por dónde te vayas."],"ojo":"Lee si piden el MÁS largo o el MÁS corto: es lo único que cambia."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('7fa40b84-9fad-4b2c-a2c4-faa1a3bb5d44'::uuid, 'multiple_choice', 'En el plano, los dos caminos miden lo mismo. Entonces:', '{"options":["Da igual cuál tomes","El A es más corto","El B es más corto","No se pueden comparar"],"correctIndex":0,"visual":{"tipo":"barras","datos":[{"etiqueta":"Camino A","valor":9},{"etiqueta":"Camino B","valor":9}]},"ayuda":{"pista":"Los dos caminos están medidos con lo mismo. Compara los dos números.","pasos":["Mira las dos barras del dibujo: cada una es un camino.","La barra más larga es el camino más largo, y la más corta el camino más corto.","Si las dos miden igual, da lo mismo por dónde te vayas."],"ojo":"Lee si piden el MÁS largo o el MÁS corto: es lo único que cambia."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('7fa40b84-9fad-4b2c-a2c4-faa1a3bb5d44'::uuid, 'multiple_choice', 'Desde tu casa, en pasos. ¿Cuál queda MÁS CERCA?', '{"options":["La tienda","El parque","Quedan igual","No se sabe"],"correctIndex":0,"visual":{"tipo":"barras","datos":[{"etiqueta":"Tienda","valor":10},{"etiqueta":"Parque","valor":25}]},"ayuda":{"pista":"Más cerca es el número más pequeño de pasos; más lejos es el más grande.","pasos":["Los pasos o las cuadras dicen cuánto hay que caminar hasta cada lugar.","Menos pasos es más cerca. Más pasos es más lejos.","Como los dos se midieron desde tu casa y con lo mismo, se pueden comparar."],"ojo":"Cerca y lejos son al revés en los números: el más cerca es el número más pequeño."}}'::jsonb, 3);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('7fa40b84-9fad-4b2c-a2c4-faa1a3bb5d44'::uuid, 'multiple_choice', 'Desde tu casa, en pasos. ¿Cuál queda MÁS LEJOS?', '{"options":["El colegio","La panadería","Quedan igual","No se sabe"],"correctIndex":0,"visual":{"tipo":"barras","datos":[{"etiqueta":"Colegio","valor":40},{"etiqueta":"Panadería","valor":15}]},"ayuda":{"pista":"Más cerca es el número más pequeño de pasos; más lejos es el más grande.","pasos":["Los pasos o las cuadras dicen cuánto hay que caminar hasta cada lugar.","Menos pasos es más cerca. Más pasos es más lejos.","Como los dos se midieron desde tu casa y con lo mismo, se pueden comparar."],"ojo":"Cerca y lejos son al revés en los números: el más cerca es el número más pequeño."}}'::jsonb, 3);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('7fa40b84-9fad-4b2c-a2c4-faa1a3bb5d44'::uuid, 'multiple_choice', 'Desde tu casa, en cuadras. ¿Cuál queda MÁS CERCA?', '{"options":["La iglesia","El parque","Quedan igual","No se sabe"],"correctIndex":0,"visual":{"tipo":"barras","datos":[{"etiqueta":"Iglesia","valor":2},{"etiqueta":"Parque","valor":5}]},"ayuda":{"pista":"Más cerca es el número más pequeño de pasos; más lejos es el más grande.","pasos":["Los pasos o las cuadras dicen cuánto hay que caminar hasta cada lugar.","Menos pasos es más cerca. Más pasos es más lejos.","Como los dos se midieron desde tu casa y con lo mismo, se pueden comparar."],"ojo":"Cerca y lejos son al revés en los números: el más cerca es el número más pequeño."}}'::jsonb, 3);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('7fa40b84-9fad-4b2c-a2c4-faa1a3bb5d44'::uuid, 'multiple_choice', 'Un camino de 3 cuadras es ___ que uno de 6 cuadras.', '{"options":["Más corto","Más largo","Igual de largo","Más ancho"],"correctIndex":0,"ayuda":{"pista":"Compara los dos números de cuadras y di cómo es el primero comparado con el segundo.","pasos":["La frase compara el primer camino CON el segundo, en ese orden.","Si el primer número es más pequeño, el primer camino es más corto.","Si los dos números son iguales, los caminos son igual de largos."],"ojo":"Lee en qué orden están. Cambiar el orden cambia la respuesta."}}'::jsonb, 4);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('7fa40b84-9fad-4b2c-a2c4-faa1a3bb5d44'::uuid, 'multiple_choice', 'Un camino de 9 cuadras es ___ que uno de 4 cuadras.', '{"options":["Más largo","Más corto","Igual de largo","Más angosto"],"correctIndex":0,"ayuda":{"pista":"Compara los dos números de cuadras y di cómo es el primero comparado con el segundo.","pasos":["La frase compara el primer camino CON el segundo, en ese orden.","Si el primer número es más pequeño, el primer camino es más corto.","Si los dos números son iguales, los caminos son igual de largos."],"ojo":"Lee en qué orden están. Cambiar el orden cambia la respuesta."}}'::jsonb, 4);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('7fa40b84-9fad-4b2c-a2c4-faa1a3bb5d44'::uuid, 'multiple_choice', 'Dos caminos de 5 cuadras cada uno son:', '{"options":["Igual de largos","Uno más largo","Uno más corto","No se pueden comparar"],"correctIndex":0,"ayuda":{"pista":"Compara los dos números de cuadras y di cómo es el primero comparado con el segundo.","pasos":["La frase compara el primer camino CON el segundo, en ese orden.","Si el primer número es más pequeño, el primer camino es más corto.","Si los dos números son iguales, los caminos son igual de largos."],"ojo":"Lee en qué orden están. Cambiar el orden cambia la respuesta."}}'::jsonb, 4);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('84eeec83-492a-4182-a48c-2563779b68f1'::uuid, 'multiple_choice', 'El lápiz está a tu DERECHA. Para cogerlo estiras:', '{"options":["La mano derecha","La mano izquierda","Las dos manos","Ninguna mano"],"correctIndex":0,"ayuda":{"pista":"Levanta de verdad la mano con la que escribes y ubícate desde ahí.","pasos":["Tu derecha y tu izquierda van contigo: dependen de para dónde estés mirando.","Lo que está a tu derecha se alcanza con la mano derecha.","Y siempre son dos: si una es la derecha, la otra es la izquierda."],"ojo":"La derecha de quien está al frente tuyo es tu izquierda. Por eso hay que ubicarse en uno mismo."}}'::jsonb, 5);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('84eeec83-492a-4182-a48c-2563779b68f1'::uuid, 'multiple_choice', 'El borrador está a tu IZQUIERDA. Para cogerlo estiras:', '{"options":["La mano izquierda","La mano derecha","Las dos manos","Ninguna mano"],"correctIndex":0,"ayuda":{"pista":"Levanta de verdad la mano con la que escribes y ubícate desde ahí.","pasos":["Tu derecha y tu izquierda van contigo: dependen de para dónde estés mirando.","Lo que está a tu derecha se alcanza con la mano derecha.","Y siempre son dos: si una es la derecha, la otra es la izquierda."],"ojo":"La derecha de quien está al frente tuyo es tu izquierda. Por eso hay que ubicarse en uno mismo."}}'::jsonb, 5);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('84eeec83-492a-4182-a48c-2563779b68f1'::uuid, 'multiple_choice', 'Si levantas la mano derecha, la otra mano es:', '{"options":["La izquierda","También la derecha","La de arriba","Ninguna"],"correctIndex":0,"ayuda":{"pista":"Levanta de verdad la mano con la que escribes y ubícate desde ahí.","pasos":["Tu derecha y tu izquierda van contigo: dependen de para dónde estés mirando.","Lo que está a tu derecha se alcanza con la mano derecha.","Y siempre son dos: si una es la derecha, la otra es la izquierda."],"ojo":"La derecha de quien está al frente tuyo es tu izquierda. Por eso hay que ubicarse en uno mismo."}}'::jsonb, 5);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('84eeec83-492a-4182-a48c-2563779b68f1'::uuid, 'multiple_choice', 'Vas caminando y das media vuelta. Ahora vas:', '{"options":["De regreso","Para el mismo lado","Hacia arriba","Sin moverte"],"correctIndex":0,"ayuda":{"pista":"Haz el giro con el cuerpo, despacio, y fíjate para dónde quedas mirando.","pasos":["Media vuelta te deja mirando justo para el lado contrario: vuelves por donde viniste.","Un cuarto de giro a la derecha te deja mirando a la derecha.","Una vuelta completa te deja mirando para donde ya ibas: es como no haber girado."],"ojo":"Media vuelta y vuelta completa suenan parecido y dejan en lados opuestos."}}'::jsonb, 6);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('84eeec83-492a-4182-a48c-2563779b68f1'::uuid, 'multiple_choice', 'Caminas de frente y giras a la derecha. Ahora vas:', '{"options":["Hacia la derecha","Hacia la izquierda","De frente","De regreso"],"correctIndex":0,"ayuda":{"pista":"Haz el giro con el cuerpo, despacio, y fíjate para dónde quedas mirando.","pasos":["Media vuelta te deja mirando justo para el lado contrario: vuelves por donde viniste.","Un cuarto de giro a la derecha te deja mirando a la derecha.","Una vuelta completa te deja mirando para donde ya ibas: es como no haber girado."],"ojo":"Media vuelta y vuelta completa suenan parecido y dejan en lados opuestos."}}'::jsonb, 6);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('84eeec83-492a-4182-a48c-2563779b68f1'::uuid, 'multiple_choice', 'Das una vuelta completa. Ahora vas:', '{"options":["Para el mismo lado","De regreso","Hacia la derecha","Hacia arriba"],"correctIndex":0,"ayuda":{"pista":"Haz el giro con el cuerpo, despacio, y fíjate para dónde quedas mirando.","pasos":["Media vuelta te deja mirando justo para el lado contrario: vuelves por donde viniste.","Un cuarto de giro a la derecha te deja mirando a la derecha.","Una vuelta completa te deja mirando para donde ya ibas: es como no haber girado."],"ojo":"Media vuelta y vuelta completa suenan parecido y dejan en lados opuestos."}}'::jsonb, 6);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('229976ae-e697-457e-8de9-be5d691067cd'::uuid, 'multiple_choice', 'En el plano, el colegio está debajo de tu casa. Para llegar:', '{"options":["Bajas","Subes","No te mueves","Das la vuelta"],"correctIndex":0,"ayuda":{"pista":"En un plano, lo que está arriba en el papel se alcanza subiendo.","pasos":["Un plano es el dibujo de un lugar visto desde arriba.","Lo que aparece arriba en el dibujo queda hacia allá; lo de abajo, hacia acá.","Para llegar, te mueves en la misma dirección en la que está dibujado."],"ojo":"Moverse al contrario de como está en el plano te aleja en vez de acercarte."}}'::jsonb, 7);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('229976ae-e697-457e-8de9-be5d691067cd'::uuid, 'multiple_choice', 'En el plano, la tienda está arriba de tu casa. Para llegar:', '{"options":["Subes","Bajas","No te mueves","Das la vuelta"],"correctIndex":0,"ayuda":{"pista":"En un plano, lo que está arriba en el papel se alcanza subiendo.","pasos":["Un plano es el dibujo de un lugar visto desde arriba.","Lo que aparece arriba en el dibujo queda hacia allá; lo de abajo, hacia acá.","Para llegar, te mueves en la misma dirección en la que está dibujado."],"ojo":"Moverse al contrario de como está en el plano te aleja en vez de acercarte."}}'::jsonb, 7);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('229976ae-e697-457e-8de9-be5d691067cd'::uuid, 'multiple_choice', 'En el plano, el parque está a la derecha. Para llegar vas:', '{"options":["A la derecha","A la izquierda","Hacia arriba","Hacia abajo"],"correctIndex":0,"ayuda":{"pista":"En un plano, lo que está arriba en el papel se alcanza subiendo.","pasos":["Un plano es el dibujo de un lugar visto desde arriba.","Lo que aparece arriba en el dibujo queda hacia allá; lo de abajo, hacia acá.","Para llegar, te mueves en la misma dirección en la que está dibujado."],"ojo":"Moverse al contrario de como está en el plano te aleja en vez de acercarte."}}'::jsonb, 7);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('229976ae-e697-457e-8de9-be5d691067cd'::uuid, 'multiple_choice', 'Estás en la puerta. El tablero está al frente. Para llegar:', '{"options":["Camino hacia el frente","Salgo del salón","Camino hacia atrás","Me quedo quieto"],"correctIndex":0,"ayuda":{"pista":"Piensa qué es lo PRIMERO que tendrías que hacer para arrancar hacia allá.","pasos":["Un recorrido se arma por pasos, y la pregunta es por el primero.","Mira dónde estás parado y hacia dónde queda lo que buscas.","El primer paso es moverte en esa dirección: al frente, cruzando, o hasta el fondo."],"ojo":"Quedarse quieto o irse para el otro lado no acerca a ninguna parte."}}'::jsonb, 8);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('229976ae-e697-457e-8de9-be5d691067cd'::uuid, 'multiple_choice', 'El baño queda pasando el patio. Para llegar primero:', '{"options":["Cruzo el patio","Entro al salón","Subo al techo","Me quedo quieto"],"correctIndex":0,"ayuda":{"pista":"Piensa qué es lo PRIMERO que tendrías que hacer para arrancar hacia allá.","pasos":["Un recorrido se arma por pasos, y la pregunta es por el primero.","Mira dónde estás parado y hacia dónde queda lo que buscas.","El primer paso es moverte en esa dirección: al frente, cruzando, o hasta el fondo."],"ojo":"Quedarse quieto o irse para el otro lado no acerca a ninguna parte."}}'::jsonb, 8);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('229976ae-e697-457e-8de9-be5d691067cd'::uuid, 'multiple_choice', 'Tu puesto está en la última fila. Para llegar:', '{"options":["Camino hasta el fondo","Me quedo en la puerta","Voy al tablero","Salgo del salón"],"correctIndex":0,"ayuda":{"pista":"Piensa qué es lo PRIMERO que tendrías que hacer para arrancar hacia allá.","pasos":["Un recorrido se arma por pasos, y la pregunta es por el primero.","Mira dónde estás parado y hacia dónde queda lo que buscas.","El primer paso es moverte en esa dirección: al frente, cruzando, o hasta el fondo."],"ojo":"Quedarse quieto o irse para el otro lado no acerca a ninguna parte."}}'::jsonb, 8);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('ffb26b99-30f8-4da2-9bb5-0255ce3cf7be'::uuid, 'multiple_choice', 'El parque queda más lejos que la tienda. Llegar allá toma:', '{"options":["Más tiempo","Menos tiempo","El mismo tiempo","Nada de tiempo"],"correctIndex":0,"ayuda":{"pista":"Más lejos es más camino, y más camino es más tiempo caminando.","pasos":["Si dos lugares están a distinta distancia, llegar a ellos toma distinto tiempo.","Al más lejano se demora más; al más cercano, menos.","Y si están a la misma distancia, llegar toma el mismo tiempo."],"ojo":"Esto vale si vas igual de rápido a los dos lados."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('ffb26b99-30f8-4da2-9bb5-0255ce3cf7be'::uuid, 'multiple_choice', 'El colegio queda más cerca que la finca. Llegar toma:', '{"options":["Menos tiempo","Más tiempo","El mismo tiempo","Nada de tiempo"],"correctIndex":0,"ayuda":{"pista":"Más lejos es más camino, y más camino es más tiempo caminando.","pasos":["Si dos lugares están a distinta distancia, llegar a ellos toma distinto tiempo.","Al más lejano se demora más; al más cercano, menos.","Y si están a la misma distancia, llegar toma el mismo tiempo."],"ojo":"Esto vale si vas igual de rápido a los dos lados."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('ffb26b99-30f8-4da2-9bb5-0255ce3cf7be'::uuid, 'multiple_choice', 'Dos casas quedan a la misma distancia. Llegar toma:', '{"options":["El mismo tiempo","Más tiempo a una","Menos tiempo a una","No se sabe"],"correctIndex":0,"ayuda":{"pista":"Más lejos es más camino, y más camino es más tiempo caminando.","pasos":["Si dos lugares están a distinta distancia, llegar a ellos toma distinto tiempo.","Al más lejano se demora más; al más cercano, menos.","Y si están a la misma distancia, llegar toma el mismo tiempo."],"ojo":"Esto vale si vas igual de rápido a los dos lados."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('ffb26b99-30f8-4da2-9bb5-0255ce3cf7be'::uuid, 'multiple_choice', '¿Cuál indicación sirve para llegar a un lugar?', '{"options":["Camina 2 cuadras y gira","Camina un rato","Queda por ahí","Es una casa bonita"],"correctIndex":0,"ayuda":{"pista":"Una buena indicación dice CUÁNTO avanzar y PARA DÓNDE girar.","pasos":["Para llegar a un sitio hay que saber dos cosas: cuánto caminar y hacia dónde.","«Camina 2 cuadras y gira» tiene las dos: un número y una dirección.","«Queda por ahí» o «es una casa bonita» no sirven: no dicen ni cuánto ni para dónde."],"ojo":"Describir cómo es el lugar no ayuda a llegar si no dices el camino."}}'::jsonb, 10);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('ffb26b99-30f8-4da2-9bb5-0255ce3cf7be'::uuid, 'multiple_choice', '¿Cuál indicación es más clara?', '{"options":["Sube 3 pisos y gira","Queda arribita","Por allá","Es grande"],"correctIndex":0,"ayuda":{"pista":"Una buena indicación dice CUÁNTO avanzar y PARA DÓNDE girar.","pasos":["Para llegar a un sitio hay que saber dos cosas: cuánto caminar y hacia dónde.","«Camina 2 cuadras y gira» tiene las dos: un número y una dirección.","«Queda por ahí» o «es una casa bonita» no sirven: no dicen ni cuánto ni para dónde."],"ojo":"Describir cómo es el lugar no ayuda a llegar si no dices el camino."}}'::jsonb, 10);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('ffb26b99-30f8-4da2-9bb5-0255ce3cf7be'::uuid, 'multiple_choice', 'Para explicar un camino sirve decir:', '{"options":["Cuántas cuadras y para dónde","Que queda lejos","Que es bonito","Que es de color azul"],"correctIndex":0,"ayuda":{"pista":"Una buena indicación dice CUÁNTO avanzar y PARA DÓNDE girar.","pasos":["Para llegar a un sitio hay que saber dos cosas: cuánto caminar y hacia dónde.","«Camina 2 cuadras y gira» tiene las dos: un número y una dirección.","«Queda por ahí» o «es una casa bonita» no sirven: no dicen ni cuánto ni para dónde."],"ojo":"Describir cómo es el lugar no ayuda a llegar si no dices el camino."}}'::jsonb, 10);
insert into learning_evidences (id, dba_id, num, texto) select '45e2dd6d-c64a-4464-ba6f-5fa9b9dc4772'::uuid, d.id, 1, 'Identifica y nombra diferencias entre objetos o grupos de objetos.' from dbas d join subjects s on s.id = d.subject_id and s.slug = 'matematicas' where d.grade = 1 and d.num = 8;
insert into learning_evidences (id, dba_id, num, texto) select '6cd9c170-5422-443a-a119-ad3dfee5cdca'::uuid, d.id, 2, 'Comunica las características identificadas y justifica las diferencias que encuentra.' from dbas d join subjects s on s.id = d.subject_id and s.slug = 'matematicas' where d.grade = 1 and d.num = 8;
insert into learning_evidences (id, dba_id, num, texto) select '2423bd85-f61c-4deb-882a-7c33d69a2fe5'::uuid, d.id, 3, 'Establece relaciones de dependencia entre magnitudes.' from dbas d join subjects s on s.id = d.subject_id and s.slug = 'matematicas' where d.grade = 1 and d.num = 8;
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('45e2dd6d-c64a-4464-ba6f-5fa9b9dc4772'::uuid, 'multiple_choice', 'Un vaso tenía 2 bolas. Ahora tiene 5. ¿Qué pasó?', '{"options":["Le pusieron más","Le quitaron","No cambió nada","Se hicieron grandes"],"correctIndex":0,"ayuda":{"pista":"Compara el número de antes con el de ahora: ¿subió o bajó?","pasos":["Mira cuánto había antes y cuánto hay ahora.","Si ahora hay más, es porque alguien agregó.","Si ahora hay menos, es porque alguien quitó, se comió o se llevó."],"ojo":"Las cosas no cambian de cantidad solas: si hay más o menos, alguien hizo algo."}}'::jsonb, 1);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('45e2dd6d-c64a-4464-ba6f-5fa9b9dc4772'::uuid, 'multiple_choice', 'Había 8 galletas. Ahora hay 3. ¿Qué pasó?', '{"options":["Se comieron unas","Pusieron más","No cambió nada","Crecieron"],"correctIndex":0,"ayuda":{"pista":"Compara el número de antes con el de ahora: ¿subió o bajó?","pasos":["Mira cuánto había antes y cuánto hay ahora.","Si ahora hay más, es porque alguien agregó.","Si ahora hay menos, es porque alguien quitó, se comió o se llevó."],"ojo":"Las cosas no cambian de cantidad solas: si hay más o menos, alguien hizo algo."}}'::jsonb, 1);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('45e2dd6d-c64a-4464-ba6f-5fa9b9dc4772'::uuid, 'multiple_choice', 'El frasco tenía 4 dulces. Ahora tiene 9. ¿Qué pasó?', '{"options":["Echaron más dulces","Sacaron dulces","No cambió nada","Se derritieron"],"correctIndex":0,"ayuda":{"pista":"Compara el número de antes con el de ahora: ¿subió o bajó?","pasos":["Mira cuánto había antes y cuánto hay ahora.","Si ahora hay más, es porque alguien agregó.","Si ahora hay menos, es porque alguien quitó, se comió o se llevó."],"ojo":"Las cosas no cambian de cantidad solas: si hay más o menos, alguien hizo algo."}}'::jsonb, 1);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('45e2dd6d-c64a-4464-ba6f-5fa9b9dc4772'::uuid, 'multiple_choice', 'Tenías 10 dulces. Ahora tienes 6. Entonces:', '{"options":["Te faltan 4","Te sobran 4","Te faltan 6","No cambió nada"],"correctIndex":0,"ayuda":{"pista":"Además de mirar si subió o bajó, cuenta CUÁNTO cambió de uno a otro.","pasos":["Primero fíjate si la cantidad subió o bajó.","Después cuenta cuánto: desde el número pequeño hasta el grande.","Ese número es lo que ganaste, lo que te falta o lo que quitaron."],"ojo":"El cambio no es ninguno de los dos números: es la diferencia entre ellos."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('45e2dd6d-c64a-4464-ba6f-5fa9b9dc4772'::uuid, 'multiple_choice', 'Tenías 7 fichas. Ahora tienes 9. Entonces:', '{"options":["Ganaste 2","Perdiste 2","Ganaste 9","No cambió nada"],"correctIndex":0,"ayuda":{"pista":"Además de mirar si subió o bajó, cuenta CUÁNTO cambió de uno a otro.","pasos":["Primero fíjate si la cantidad subió o bajó.","Después cuenta cuánto: desde el número pequeño hasta el grande.","Ese número es lo que ganaste, lo que te falta o lo que quitaron."],"ojo":"El cambio no es ninguno de los dos números: es la diferencia entre ellos."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('45e2dd6d-c64a-4464-ba6f-5fa9b9dc4772'::uuid, 'multiple_choice', 'Había 12 sillas. Ahora hay 8. Entonces:', '{"options":["Quitaron 4","Pusieron 4","Quitaron 8","No cambió nada"],"correctIndex":0,"ayuda":{"pista":"Además de mirar si subió o bajó, cuenta CUÁNTO cambió de uno a otro.","pasos":["Primero fíjate si la cantidad subió o bajó.","Después cuenta cuánto: desde el número pequeño hasta el grande.","Ese número es lo que ganaste, lo que te falta o lo que quitaron."],"ojo":"El cambio no es ninguno de los dos números: es la diferencia entre ellos."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('45e2dd6d-c64a-4464-ba6f-5fa9b9dc4772'::uuid, 'multiple_choice', 'Un grupo tiene 4 bolas y el otro también 4. Son:', '{"options":["Iguales en cantidad","Distintos en cantidad","Uno tiene más","No se sabe"],"correctIndex":0,"ayuda":{"pista":"Compara los dos números y fíjate en el ORDEN en que los nombra la frase.","pasos":["Si los dos números son iguales, los grupos tienen la misma cantidad.","Si son distintos, el del número más grande tiene más.","Fíjate cuál se nombró primero y cuál segundo, porque la respuesta los llama así."],"ojo":"Saber cuál tiene más no basta: hay que decir si es el primero o el segundo."}}'::jsonb, 3);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('45e2dd6d-c64a-4464-ba6f-5fa9b9dc4772'::uuid, 'multiple_choice', 'Un grupo tiene 5 fichas y el otro 8. Entonces:', '{"options":["El segundo tiene más","El primero tiene más","Son iguales","No se sabe"],"correctIndex":0,"ayuda":{"pista":"Compara los dos números y fíjate en el ORDEN en que los nombra la frase.","pasos":["Si los dos números son iguales, los grupos tienen la misma cantidad.","Si son distintos, el del número más grande tiene más.","Fíjate cuál se nombró primero y cuál segundo, porque la respuesta los llama así."],"ojo":"Saber cuál tiene más no basta: hay que decir si es el primero o el segundo."}}'::jsonb, 3);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('45e2dd6d-c64a-4464-ba6f-5fa9b9dc4772'::uuid, 'multiple_choice', 'Un grupo tiene 9 lápices y el otro 6. Entonces:', '{"options":["El primero tiene más","El segundo tiene más","Son iguales","No se sabe"],"correctIndex":0,"ayuda":{"pista":"Compara los dos números y fíjate en el ORDEN en que los nombra la frase.","pasos":["Si los dos números son iguales, los grupos tienen la misma cantidad.","Si son distintos, el del número más grande tiene más.","Fíjate cuál se nombró primero y cuál segundo, porque la respuesta los llama así."],"ojo":"Saber cuál tiene más no basta: hay que decir si es el primero o el segundo."}}'::jsonb, 3);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('6cd9c170-5422-443a-a119-ad3dfee5cdca'::uuid, 'multiple_choice', 'Un grupo tiene 3 patos. El otro, 3 patos con sombrero.', '{"options":["Se diferencian en el sombrero","Se diferencian en la cantidad","No se diferencian","Se diferencian en el agua"],"correctIndex":0,"ayuda":{"pista":"Los dos grupos tienen lo mismo en cantidad. Busca en qué se ven distintos.","pasos":["Dos cosas se pueden diferenciar en la cantidad o en cómo son.","Aquí la cantidad es la misma, así que la diferencia está en otra parte.","Mírales el tamaño, si tienen algo puesto, o si están llenos o vacíos."],"ojo":"Si hay la misma cantidad en los dos, la diferencia NO puede ser la cantidad."}}'::jsonb, 4);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('6cd9c170-5422-443a-a119-ad3dfee5cdca'::uuid, 'multiple_choice', 'Dos perros iguales, uno grande y uno chiquito.', '{"options":["Se diferencian en el tamaño","Se diferencian en la cantidad","No se diferencian","Se diferencian en el nombre"],"correctIndex":0,"ayuda":{"pista":"Los dos grupos tienen lo mismo en cantidad. Busca en qué se ven distintos.","pasos":["Dos cosas se pueden diferenciar en la cantidad o en cómo son.","Aquí la cantidad es la misma, así que la diferencia está en otra parte.","Mírales el tamaño, si tienen algo puesto, o si están llenos o vacíos."],"ojo":"Si hay la misma cantidad en los dos, la diferencia NO puede ser la cantidad."}}'::jsonb, 4);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('6cd9c170-5422-443a-a119-ad3dfee5cdca'::uuid, 'multiple_choice', 'Dos vasos iguales, uno lleno y otro vacío.', '{"options":["Se diferencian en el agua","Se diferencian en la forma","No se diferencian","Se diferencian en el color"],"correctIndex":0,"ayuda":{"pista":"Los dos grupos tienen lo mismo en cantidad. Busca en qué se ven distintos.","pasos":["Dos cosas se pueden diferenciar en la cantidad o en cómo son.","Aquí la cantidad es la misma, así que la diferencia está en otra parte.","Mírales el tamaño, si tienen algo puesto, o si están llenos o vacíos."],"ojo":"Si hay la misma cantidad en los dos, la diferencia NO puede ser la cantidad."}}'::jsonb, 4);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('6cd9c170-5422-443a-a119-ad3dfee5cdca'::uuid, 'multiple_choice', '¿En qué se diferencian estos dos grupos?', '{"options":["Uno tiene más bolas","En el color","En la forma","En nada"],"correctIndex":0,"visual":{"tipo":"comparar","icono":"🔴","a":{"etiqueta":"Grupo 1","cantidad":3},"b":{"etiqueta":"Grupo 2","cantidad":5}},"ayuda":{"pista":"Las dos filas del dibujo son del mismo objeto. Mira cuál llega más lejos.","pasos":["Los dos grupos tienen el mismo dibujo, del mismo color y del mismo tamaño.","Entonces la única diferencia posible es cuántos hay en cada uno.","La fila que llega más lejos es la que tiene más."],"ojo":"Si son del mismo color y forma, la diferencia no puede ser el color ni la forma."}}'::jsonb, 5);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('6cd9c170-5422-443a-a119-ad3dfee5cdca'::uuid, 'multiple_choice', '¿En qué se diferencian estos dos grupos?', '{"options":["Uno tiene más estrellas","En el color","En el tamaño","En nada"],"correctIndex":0,"visual":{"tipo":"comparar","icono":"⭐","a":{"etiqueta":"Grupo 1","cantidad":2},"b":{"etiqueta":"Grupo 2","cantidad":6}},"ayuda":{"pista":"Las dos filas del dibujo son del mismo objeto. Mira cuál llega más lejos.","pasos":["Los dos grupos tienen el mismo dibujo, del mismo color y del mismo tamaño.","Entonces la única diferencia posible es cuántos hay en cada uno.","La fila que llega más lejos es la que tiene más."],"ojo":"Si son del mismo color y forma, la diferencia no puede ser el color ni la forma."}}'::jsonb, 5);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('6cd9c170-5422-443a-a119-ad3dfee5cdca'::uuid, 'multiple_choice', '¿Cuál grupo tiene más?', '{"options":["El grupo 1","El grupo 2","Los dos igual","No se sabe"],"correctIndex":0,"visual":{"tipo":"comparar","icono":"🟦","a":{"etiqueta":"Grupo 1","cantidad":4},"b":{"etiqueta":"Grupo 2","cantidad":2}},"ayuda":{"pista":"Las dos filas del dibujo son del mismo objeto. Mira cuál llega más lejos.","pasos":["Los dos grupos tienen el mismo dibujo, del mismo color y del mismo tamaño.","Entonces la única diferencia posible es cuántos hay en cada uno.","La fila que llega más lejos es la que tiene más."],"ojo":"Si son del mismo color y forma, la diferencia no puede ser el color ni la forma."}}'::jsonb, 5);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('2423bd85-f61c-4deb-882a-7c33d69a2fe5'::uuid, 'multiple_choice', 'Sacas agua de la jarra para llenar vasos. En la jarra:', '{"options":["Queda menos agua","Queda más agua","Queda igual","El agua se congela"],"correctIndex":0,"ayuda":{"pista":"Si sacas de un sitio queda menos allí; si echas, queda más.","pasos":["Lo que sale de un lugar tiene que salir de algún lado: del que lo tenía.","Sacar agua de la jarra deja menos agua en la jarra.","Echarle agua al balde deja más agua en el balde."],"ojo":"El agua no desaparece ni aparece: cambia de sitio."}}'::jsonb, 6);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('2423bd85-f61c-4deb-882a-7c33d69a2fe5'::uuid, 'multiple_choice', 'Le echas más agua al balde. En el balde:', '{"options":["Hay más agua","Hay menos agua","Queda igual","El agua se seca"],"correctIndex":0,"ayuda":{"pista":"Si sacas de un sitio queda menos allí; si echas, queda más.","pasos":["Lo que sale de un lugar tiene que salir de algún lado: del que lo tenía.","Sacar agua de la jarra deja menos agua en la jarra.","Echarle agua al balde deja más agua en el balde."],"ojo":"El agua no desaparece ni aparece: cambia de sitio."}}'::jsonb, 6);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('2423bd85-f61c-4deb-882a-7c33d69a2fe5'::uuid, 'multiple_choice', 'Repartes las galletas del paquete. En el paquete:', '{"options":["Quedan menos","Quedan más","Quedan igual","Se hacen grandes"],"correctIndex":0,"ayuda":{"pista":"Si sacas de un sitio queda menos allí; si echas, queda más.","pasos":["Lo que sale de un lugar tiene que salir de algún lado: del que lo tenía.","Sacar agua de la jarra deja menos agua en la jarra.","Echarle agua al balde deja más agua en el balde."],"ojo":"El agua no desaparece ni aparece: cambia de sitio."}}'::jsonb, 6);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('2423bd85-f61c-4deb-882a-7c33d69a2fe5'::uuid, 'multiple_choice', 'Suben más personas al bus. Los puestos libres:', '{"options":["Son menos","Son más","Son los mismos","Se vuelven sillas"],"correctIndex":0,"ayuda":{"pista":"Ojo: aquí no preguntan por las personas, preguntan por los puestos LIBRES.","pasos":["En un bus hay un número fijo de puestos: unos ocupados y otros libres.","Si suben más personas, ocupan puestos, así que quedan menos libres.","Si se bajan, dejan puestos, así que quedan más libres."],"ojo":"Cuando una cosa sube, la otra baja. Lee bien por cuál de las dos preguntan."}}'::jsonb, 7);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('2423bd85-f61c-4deb-882a-7c33d69a2fe5'::uuid, 'multiple_choice', 'Se bajan personas del bus. Los puestos libres:', '{"options":["Son más","Son menos","Son los mismos","Desaparecen"],"correctIndex":0,"ayuda":{"pista":"Ojo: aquí no preguntan por las personas, preguntan por los puestos LIBRES.","pasos":["En un bus hay un número fijo de puestos: unos ocupados y otros libres.","Si suben más personas, ocupan puestos, así que quedan menos libres.","Si se bajan, dejan puestos, así que quedan más libres."],"ojo":"Cuando una cosa sube, la otra baja. Lee bien por cuál de las dos preguntan."}}'::jsonb, 7);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('2423bd85-f61c-4deb-882a-7c33d69a2fe5'::uuid, 'multiple_choice', 'Llegan más niños al salón. Las sillas vacías:', '{"options":["Son menos","Son más","Son las mismas","Se rompen"],"correctIndex":0,"ayuda":{"pista":"Ojo: aquí no preguntan por las personas, preguntan por los puestos LIBRES.","pasos":["En un bus hay un número fijo de puestos: unos ocupados y otros libres.","Si suben más personas, ocupan puestos, así que quedan menos libres.","Si se bajan, dejan puestos, así que quedan más libres."],"ojo":"Cuando una cosa sube, la otra baja. Lee bien por cuál de las dos preguntan."}}'::jsonb, 7);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('2423bd85-f61c-4deb-882a-7c33d69a2fe5'::uuid, 'multiple_choice', 'Mientras más crece un árbol, el árbol es:', '{"options":["Más alto","Más bajito","Igual de alto","Más delgado"],"correctIndex":0,"ayuda":{"pista":"Piensa qué le pasa a lo que está alrededor cuando la cosa se hace más grande.","pasos":["Cuando algo crece, ocupa más espacio del que ocupaba antes.","Un árbol que crece queda más alto; un globo que se infla queda más grande.","Y la ropa, que no creció, le queda más apretada al niño que sí creció."],"ojo":"La ropa no encogió: fue el niño el que creció."}}'::jsonb, 8);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('2423bd85-f61c-4deb-882a-7c33d69a2fe5'::uuid, 'multiple_choice', 'Mientras más crece un niño, su ropa le queda:', '{"options":["Más apretada","Más grande","Igual","Más suave"],"correctIndex":0,"ayuda":{"pista":"Piensa qué le pasa a lo que está alrededor cuando la cosa se hace más grande.","pasos":["Cuando algo crece, ocupa más espacio del que ocupaba antes.","Un árbol que crece queda más alto; un globo que se infla queda más grande.","Y la ropa, que no creció, le queda más apretada al niño que sí creció."],"ojo":"La ropa no encogió: fue el niño el que creció."}}'::jsonb, 8);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('2423bd85-f61c-4deb-882a-7c33d69a2fe5'::uuid, 'multiple_choice', 'Mientras más inflas un globo, se pone:', '{"options":["Más grande","Más pequeño","Igual","Más pesado"],"correctIndex":0,"ayuda":{"pista":"Piensa qué le pasa a lo que está alrededor cuando la cosa se hace más grande.","pasos":["Cuando algo crece, ocupa más espacio del que ocupaba antes.","Un árbol que crece queda más alto; un globo que se infla queda más grande.","Y la ropa, que no creció, le queda más apretada al niño que sí creció."],"ojo":"La ropa no encogió: fue el niño el que creció."}}'::jsonb, 8);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('2423bd85-f61c-4deb-882a-7c33d69a2fe5'::uuid, 'multiple_choice', 'Si caminas más rápido, llegas:', '{"options":["Más temprano","Más tarde","A la misma hora","Nunca"],"correctIndex":0,"ayuda":{"pista":"Piensa en el reloj: ir más rápido gasta menos tiempo.","pasos":["Si vas más rápido por el mismo camino, gastas menos tiempo y llegas antes.","Si vas más despacio, gastas más tiempo y llegas después.","Y si el camino es más largo, aunque vayas igual de rápido, te demoras más."],"ojo":"Más rápido y más tiempo no van juntos: cuando una sube, la otra baja."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('2423bd85-f61c-4deb-882a-7c33d69a2fe5'::uuid, 'multiple_choice', 'Si caminas más despacio, llegas:', '{"options":["Más tarde","Más temprano","A la misma hora","Nunca"],"correctIndex":0,"ayuda":{"pista":"Piensa en el reloj: ir más rápido gasta menos tiempo.","pasos":["Si vas más rápido por el mismo camino, gastas menos tiempo y llegas antes.","Si vas más despacio, gastas más tiempo y llegas después.","Y si el camino es más largo, aunque vayas igual de rápido, te demoras más."],"ojo":"Más rápido y más tiempo no van juntos: cuando una sube, la otra baja."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('2423bd85-f61c-4deb-882a-7c33d69a2fe5'::uuid, 'multiple_choice', 'Si el camino es más largo, te demoras:', '{"options":["Más tiempo","Menos tiempo","El mismo tiempo","Nada"],"correctIndex":0,"ayuda":{"pista":"Piensa en el reloj: ir más rápido gasta menos tiempo.","pasos":["Si vas más rápido por el mismo camino, gastas menos tiempo y llegas antes.","Si vas más despacio, gastas más tiempo y llegas después.","Y si el camino es más largo, aunque vayas igual de rápido, te demoras más."],"ojo":"Más rápido y más tiempo no van juntos: cuando una sube, la otra baja."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('2423bd85-f61c-4deb-882a-7c33d69a2fe5'::uuid, 'multiple_choice', 'Mientras más pesa algo, para levantarlo necesitas:', '{"options":["Más fuerza","Menos fuerza","La misma fuerza","Nada de fuerza"],"correctIndex":0,"ayuda":{"pista":"Pregúntate si las dos cosas suben juntas o si una sube cuando la otra baja.","pasos":["Mientras más pesa algo, más fuerza hay que hacer: las dos suben juntas.","Mientras más liviano, más fácil de levantar: una sube y la otra también, pero de facilidad.","Mientras más grande la caja, más cosas le caben."],"ojo":"Fíjate si la pregunta va con «más pesa» o con «más liviano»: apuntan a lados contrarios."}}'::jsonb, 10);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('2423bd85-f61c-4deb-882a-7c33d69a2fe5'::uuid, 'multiple_choice', 'Mientras más liviano es algo, levantarlo es:', '{"options":["Más fácil","Más difícil","Igual de difícil","Imposible"],"correctIndex":0,"ayuda":{"pista":"Pregúntate si las dos cosas suben juntas o si una sube cuando la otra baja.","pasos":["Mientras más pesa algo, más fuerza hay que hacer: las dos suben juntas.","Mientras más liviano, más fácil de levantar: una sube y la otra también, pero de facilidad.","Mientras más grande la caja, más cosas le caben."],"ojo":"Fíjate si la pregunta va con «más pesa» o con «más liviano»: apuntan a lados contrarios."}}'::jsonb, 10);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('2423bd85-f61c-4deb-882a-7c33d69a2fe5'::uuid, 'multiple_choice', 'Mientras más grande es la caja, le cabe:', '{"options":["Más cosas","Menos cosas","Las mismas cosas","Nada"],"correctIndex":0,"ayuda":{"pista":"Pregúntate si las dos cosas suben juntas o si una sube cuando la otra baja.","pasos":["Mientras más pesa algo, más fuerza hay que hacer: las dos suben juntas.","Mientras más liviano, más fácil de levantar: una sube y la otra también, pero de facilidad.","Mientras más grande la caja, más cosas le caben."],"ojo":"Fíjate si la pregunta va con «más pesa» o con «más liviano»: apuntan a lados contrarios."}}'::jsonb, 10);
insert into learning_evidences (id, dba_id, num, texto) select '4fe7426a-e5c4-41ed-b75d-93efde483d1c'::uuid, d.id, 1, 'Propone números que satisfacen una igualdad con sumas y restas.' from dbas d join subjects s on s.id = d.subject_id and s.slug = 'matematicas' where d.grade = 1 and d.num = 9;
