insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('90fe94b2-af99-425d-a454-f855c83eed3e'::uuid, 'multiple_choice', 'El signo = dice que los dos lados:', '{"options":["Valen igual","Se suman","Son distintos","Se restan"],"correctIndex":0,"ayuda":{"pista":"El signo = es una balanza: dice que los dos lados pesan lo mismo.","pasos":["El signo = no significa «aquí va la respuesta». Significa «vale lo mismo que».","En 3 + 2 = 5 está diciendo que 3 + 2 y 5 son la misma cantidad escrita de dos maneras.","Por eso solo se escribe = cuando los dos lados valen igual."],"ojo":"Es el error más común de todos: creer que = es la orden de calcular."}}'::jsonb, 8);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('90fe94b2-af99-425d-a454-f855c83eed3e'::uuid, 'multiple_choice', 'Si los dos lados valen lo mismo, se escribe:', '{"options":["El signo =","El signo +","El signo −","Nada"],"correctIndex":0,"ayuda":{"pista":"El signo = es una balanza: dice que los dos lados pesan lo mismo.","pasos":["El signo = no significa «aquí va la respuesta». Significa «vale lo mismo que».","En 3 + 2 = 5 está diciendo que 3 + 2 y 5 son la misma cantidad escrita de dos maneras.","Por eso solo se escribe = cuando los dos lados valen igual."],"ojo":"Es el error más común de todos: creer que = es la orden de calcular."}}'::jsonb, 8);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('90fe94b2-af99-425d-a454-f855c83eed3e'::uuid, 'multiple_choice', 'En 3 + 2 = 5, el signo = dice que:', '{"options":["3 + 2 vale lo mismo que 5","Hay que sumar 5","5 es mayor","Hay que restar"],"correctIndex":0,"ayuda":{"pista":"El signo = es una balanza: dice que los dos lados pesan lo mismo.","pasos":["El signo = no significa «aquí va la respuesta». Significa «vale lo mismo que».","En 3 + 2 = 5 está diciendo que 3 + 2 y 5 son la misma cantidad escrita de dos maneras.","Por eso solo se escribe = cuando los dos lados valen igual."],"ojo":"Es el error más común de todos: creer que = es la orden de calcular."}}'::jsonb, 8);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('90fe94b2-af99-425d-a454-f855c83eed3e'::uuid, 'multiple_choice', 'En 4 + ? = 4 + 6, el número que falta es:', '{"options":["Igual a 6","Mayor que 6","Menor que 6","Cualquiera"],"correctIndex":0,"ayuda":{"pista":"Si los dos lados tienen el mismo número repetido, el que falta también es igual al que sobra.","pasos":["Mira los dos lados y busca el número que se repite en los dos.","Si ese número está en los dos lados, se equilibra solo y no hay que hacerle nada.","Entonces lo que falta tiene que ser igual al número que quedó del otro lado."],"ojo":"Aquí no hay que sumar nada: basta con comparar los dos lados."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('90fe94b2-af99-425d-a454-f855c83eed3e'::uuid, 'multiple_choice', 'En 7 + ? = 7 + 2, el número que falta es:', '{"options":["Igual a 2","Mayor que 2","Menor que 2","Cualquiera"],"correctIndex":0,"ayuda":{"pista":"Si los dos lados tienen el mismo número repetido, el que falta también es igual al que sobra.","pasos":["Mira los dos lados y busca el número que se repite en los dos.","Si ese número está en los dos lados, se equilibra solo y no hay que hacerle nada.","Entonces lo que falta tiene que ser igual al número que quedó del otro lado."],"ojo":"Aquí no hay que sumar nada: basta con comparar los dos lados."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('90fe94b2-af99-425d-a454-f855c83eed3e'::uuid, 'multiple_choice', 'En ? + 5 = 3 + 5, el número que falta es:', '{"options":["Igual a 3","Mayor que 3","Menor que 3","Cualquiera"],"correctIndex":0,"ayuda":{"pista":"Si los dos lados tienen el mismo número repetido, el que falta también es igual al que sobra.","pasos":["Mira los dos lados y busca el número que se repite en los dos.","Si ese número está en los dos lados, se equilibra solo y no hay que hacerle nada.","Entonces lo que falta tiene que ser igual al número que quedó del otro lado."],"ojo":"Aquí no hay que sumar nada: basta con comparar los dos lados."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('3aa74f42-6569-4eb3-bd03-5578ed891927'::uuid, 'multiple_choice', 'Mira las dos igualdades. ¿A qué más es igual 3 + 4?', '{"options":["5 + 2","5 − 2","3 + 2","7 + 7"],"correctIndex":0,"operation":"3 + 4 = 7   y   7 = 5 + 2"}'::jsonb, 10);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('3aa74f42-6569-4eb3-bd03-5578ed891927'::uuid, 'multiple_choice', 'Mira las dos igualdades. ¿A qué más es igual 2 + 6?', '{"options":["4 + 4","4 − 4","2 + 4","8 + 8"],"correctIndex":0,"operation":"2 + 6 = 8   y   8 = 4 + 4"}'::jsonb, 10);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('3aa74f42-6569-4eb3-bd03-5578ed891927'::uuid, 'multiple_choice', 'Mira las dos igualdades. ¿A qué más es igual 1 + 5?', '{"options":["3 + 3","3 − 3","1 + 3","6 + 6"],"correctIndex":0,"operation":"1 + 5 = 6   y   6 = 3 + 3"}'::jsonb, 10);
insert into learning_evidences (id, dba_id, num, texto) select 'eb4cf05a-7be7-49ab-8b21-4288aa4bfe99'::uuid, d.id, 1, 'Identifica en fichas u objetos reales los valores de la variable en estudio.' from dbas d join subjects s on s.id = d.subject_id and s.slug = 'matematicas' where d.grade = 1 and d.num = 10;
insert into learning_evidences (id, dba_id, num, texto) select 'baea294a-44b5-4378-8a4a-27d469e782b6'::uuid, d.id, 2, 'Organiza los datos en tablas de conteo y/o en pictogramas sin escala.' from dbas d join subjects s on s.id = d.subject_id and s.slug = 'matematicas' where d.grade = 1 and d.num = 10;
insert into learning_evidences (id, dba_id, num, texto) select '2c514df6-234c-48f8-8fbd-8705c365ed2b'::uuid, d.id, 3, 'Lee la información presentada en tablas de conteo y/o pictogramas sin escala (1 a 1).' from dbas d join subjects s on s.id = d.subject_id and s.slug = 'matematicas' where d.grade = 1 and d.num = 10;
insert into learning_evidences (id, dba_id, num, texto) select 'e0da0b73-4c84-4939-8554-718a89b59f3e'::uuid, d.id, 4, 'Comunica los resultados respondiendo preguntas tales como: ¿cuántos hay en total?, ¿cuántos hay de cada dato?, ¿cuál es el dato que más se repite?, ¿cuál es el dato que menos aparece?' from dbas d join subjects s on s.id = d.subject_id and s.slug = 'matematicas' where d.grade = 1 and d.num = 10;
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('2c514df6-234c-48f8-8fbd-8705c365ed2b'::uuid, 'multiple_choice', 'Cada chocolate es 1 niño. ¿Cuántos lo quieren?', '{"options":["4","3","5","8"],"correctIndex":0,"visual":{"tipo":"contar","icono":"🍫","cantidad":4},"ayuda":{"pista":"Cada dibujo vale 1 niño. Cuenta los dibujos, uno por uno.","pasos":["En un pictograma, cada dibujo representa a alguien o a algo.","Aquí cada dibujo es un niño, así que la cantidad de dibujos es la cantidad de niños.","Cuéntalos tocándolos con el dedo para no repetir ni saltarte ninguno."],"ojo":"No hay que sumar ni multiplicar: cada dibujo vale exactamente uno."}}'::jsonb, 1);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('2c514df6-234c-48f8-8fbd-8705c365ed2b'::uuid, 'multiple_choice', 'Cada fresa es 1 niño. ¿Cuántos la quieren?', '{"options":["6","5","7","12"],"correctIndex":0,"visual":{"tipo":"contar","icono":"🍓","cantidad":6},"ayuda":{"pista":"Cada dibujo vale 1 niño. Cuenta los dibujos, uno por uno.","pasos":["En un pictograma, cada dibujo representa a alguien o a algo.","Aquí cada dibujo es un niño, así que la cantidad de dibujos es la cantidad de niños.","Cuéntalos tocándolos con el dedo para no repetir ni saltarte ninguno."],"ojo":"No hay que sumar ni multiplicar: cada dibujo vale exactamente uno."}}'::jsonb, 1);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('2c514df6-234c-48f8-8fbd-8705c365ed2b'::uuid, 'multiple_choice', 'Cada banano es 1 niño. ¿Cuántos lo quieren?', '{"options":["3","2","4","6"],"correctIndex":0,"visual":{"tipo":"contar","icono":"🍌","cantidad":3},"ayuda":{"pista":"Cada dibujo vale 1 niño. Cuenta los dibujos, uno por uno.","pasos":["En un pictograma, cada dibujo representa a alguien o a algo.","Aquí cada dibujo es un niño, así que la cantidad de dibujos es la cantidad de niños.","Cuéntalos tocándolos con el dedo para no repetir ni saltarte ninguno."],"ojo":"No hay que sumar ni multiplicar: cada dibujo vale exactamente uno."}}'::jsonb, 1);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('2c514df6-234c-48f8-8fbd-8705c365ed2b'::uuid, 'multiple_choice', 'Cada dibujo es 1 perro. ¿Cuántos perros hay?', '{"options":["6","1","12","3"],"correctIndex":0,"visual":{"tipo":"contar","icono":"🐶","cantidad":6},"ayuda":{"pista":"Cada dibujo vale 1. Cuéntalos tocándolos con el dedo.","pasos":["Un pictograma cuenta con dibujos en vez de con números.","Como cada dibujo vale 1, la respuesta es cuántos dibujos hay.","Cuenta despacio y toca cada uno para no contar ninguno dos veces."],"ojo":"Contar de dos en dos aquí da el doble: cada dibujo es uno, no dos."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('2c514df6-234c-48f8-8fbd-8705c365ed2b'::uuid, 'multiple_choice', 'Cada dibujo es 1 gato. ¿Cuántos gatos hay?', '{"options":["5","1","10","3"],"correctIndex":0,"visual":{"tipo":"contar","icono":"🐱","cantidad":5},"ayuda":{"pista":"Cada dibujo vale 1. Cuéntalos tocándolos con el dedo.","pasos":["Un pictograma cuenta con dibujos en vez de con números.","Como cada dibujo vale 1, la respuesta es cuántos dibujos hay.","Cuenta despacio y toca cada uno para no contar ninguno dos veces."],"ojo":"Contar de dos en dos aquí da el doble: cada dibujo es uno, no dos."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('2c514df6-234c-48f8-8fbd-8705c365ed2b'::uuid, 'multiple_choice', 'Cada dibujo es 1 pájaro. ¿Cuántos pájaros hay?', '{"options":["7","1","14","4"],"correctIndex":0,"visual":{"tipo":"contar","icono":"🐦","cantidad":7},"ayuda":{"pista":"Cada dibujo vale 1. Cuéntalos tocándolos con el dedo.","pasos":["Un pictograma cuenta con dibujos en vez de con números.","Como cada dibujo vale 1, la respuesta es cuántos dibujos hay.","Cuenta despacio y toca cada uno para no contar ninguno dos veces."],"ojo":"Contar de dos en dos aquí da el doble: cada dibujo es uno, no dos."}}'::jsonb, 2);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('baea294a-44b5-4378-8a4a-27d469e782b6'::uuid, 'multiple_choice', 'En una tabla de conteo, las rayitas sirven para:', '{"options":["Contar cuántos hay","Dibujar","Medir el largo","Decir la hora"],"correctIndex":0,"ayuda":{"pista":"Una rayita es una anotación: cada vez que pasa algo, haces una.","pasos":["La tabla de conteo sirve para ir anotando mientras cuentas, sin perder la cuenta.","Cada vez que alguien vota o que aparece algo, haces UNA rayita.","Al final cuentas las rayitas y ese número es el total."],"ojo":"Cada rayita vale uno. Cinco rayitas son cinco, no cinco grupos."}}'::jsonb, 3);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('baea294a-44b5-4378-8a4a-27d469e782b6'::uuid, 'multiple_choice', 'Si haces 5 rayitas en la tabla, eso quiere decir:', '{"options":["Que hay 5","Que hay 1","Que hay 10","Que no hay"],"correctIndex":0,"ayuda":{"pista":"Una rayita es una anotación: cada vez que pasa algo, haces una.","pasos":["La tabla de conteo sirve para ir anotando mientras cuentas, sin perder la cuenta.","Cada vez que alguien vota o que aparece algo, haces UNA rayita.","Al final cuentas las rayitas y ese número es el total."],"ojo":"Cada rayita vale uno. Cinco rayitas son cinco, no cinco grupos."}}'::jsonb, 3);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('baea294a-44b5-4378-8a4a-27d469e782b6'::uuid, 'multiple_choice', 'Para anotar cada voto en la tabla, haces:', '{"options":["Una rayita","Un círculo grande","Una letra","Nada"],"correctIndex":0,"ayuda":{"pista":"Una rayita es una anotación: cada vez que pasa algo, haces una.","pasos":["La tabla de conteo sirve para ir anotando mientras cuentas, sin perder la cuenta.","Cada vez que alguien vota o que aparece algo, haces UNA rayita.","Al final cuentas las rayitas y ese número es el total."],"ojo":"Cada rayita vale uno. Cinco rayitas son cinco, no cinco grupos."}}'::jsonb, 3);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('eb4cf05a-7be7-49ab-8b21-4288aa4bfe99'::uuid, 'multiple_choice', 'En una encuesta de mascota favorita se cuenta:', '{"options":["Cuántos eligen cada una","El tamaño de la mascota","El nombre de los niños","La edad de los niños"],"correctIndex":0,"ayuda":{"pista":"En una encuesta se cuenta CUÁNTOS eligieron cada respuesta.","pasos":["Una encuesta empieza con una pregunta y varias respuestas posibles.","Cada persona elige una, y lo que se anota es cuántas personas eligieron cada cual.","Al final se compara: la que más eligieron es la favorita del grupo."],"ojo":"No se cuenta el tamaño ni la edad de nadie: se cuentan las respuestas."}}'::jsonb, 4);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('eb4cf05a-7be7-49ab-8b21-4288aa4bfe99'::uuid, 'multiple_choice', 'En una encuesta de color favorito se cuenta:', '{"options":["Cuántos eligen cada color","El tamaño del salón","La edad de los niños","El día de hoy"],"correctIndex":0,"ayuda":{"pista":"En una encuesta se cuenta CUÁNTOS eligieron cada respuesta.","pasos":["Una encuesta empieza con una pregunta y varias respuestas posibles.","Cada persona elige una, y lo que se anota es cuántas personas eligieron cada cual.","Al final se compara: la que más eligieron es la favorita del grupo."],"ojo":"No se cuenta el tamaño ni la edad de nadie: se cuentan las respuestas."}}'::jsonb, 4);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('eb4cf05a-7be7-49ab-8b21-4288aa4bfe99'::uuid, 'multiple_choice', 'En una encuesta de deporte favorito se cuenta:', '{"options":["Cuántos eligen cada deporte","Quién corre más rápido","El tamaño de la cancha","La hora del recreo"],"correctIndex":0,"ayuda":{"pista":"En una encuesta se cuenta CUÁNTOS eligieron cada respuesta.","pasos":["Una encuesta empieza con una pregunta y varias respuestas posibles.","Cada persona elige una, y lo que se anota es cuántas personas eligieron cada cual.","Al final se compara: la que más eligieron es la favorita del grupo."],"ojo":"No se cuenta el tamaño ni la edad de nadie: se cuentan las respuestas."}}'::jsonb, 4);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('eb4cf05a-7be7-49ab-8b21-4288aa4bfe99'::uuid, 'multiple_choice', 'Para saber la fruta preferida del salón, preguntas a:', '{"options":["Todos los niños","Solo a tu amigo","Solo a la profe","A nadie"],"correctIndex":0,"ayuda":{"pista":"Si quieres saber lo que piensa el curso entero, tienes que preguntarle al curso entero.","pasos":["Una encuesta habla del grupo al que se le preguntó, no de otro.","Si le preguntas a todo el curso, el resultado dice lo que piensa el curso.","Si le preguntas solo a dos, el resultado dice lo que piensan esos dos y nada más."],"ojo":"Preguntarle a pocos no está mal: lo que está mal es creer que eso habla de todos."}}'::jsonb, 5);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('eb4cf05a-7be7-49ab-8b21-4288aa4bfe99'::uuid, 'multiple_choice', 'Para saber el color favorito del curso, preguntas a:', '{"options":["Todo el curso","Solo a uno","Solo a la profe","A nadie"],"correctIndex":0,"ayuda":{"pista":"Si quieres saber lo que piensa el curso entero, tienes que preguntarle al curso entero.","pasos":["Una encuesta habla del grupo al que se le preguntó, no de otro.","Si le preguntas a todo el curso, el resultado dice lo que piensa el curso.","Si le preguntas solo a dos, el resultado dice lo que piensan esos dos y nada más."],"ojo":"Preguntarle a pocos no está mal: lo que está mal es creer que eso habla de todos."}}'::jsonb, 5);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('eb4cf05a-7be7-49ab-8b21-4288aa4bfe99'::uuid, 'multiple_choice', 'Si solo preguntas a 2 niños, el resultado:', '{"options":["No dice lo del curso entero","Dice lo del curso entero","Es siempre correcto","No sirve para nada"],"correctIndex":0,"ayuda":{"pista":"Si quieres saber lo que piensa el curso entero, tienes que preguntarle al curso entero.","pasos":["Una encuesta habla del grupo al que se le preguntó, no de otro.","Si le preguntas a todo el curso, el resultado dice lo que piensa el curso.","Si le preguntas solo a dos, el resultado dice lo que piensan esos dos y nada más."],"ojo":"Preguntarle a pocos no está mal: lo que está mal es creer que eso habla de todos."}}'::jsonb, 5);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('e0da0b73-4c84-4939-8554-718a89b59f3e'::uuid, 'multiple_choice', 'Votamos el color favorito. ¿Cuál ganó?', '{"options":["Azul","Rojo","Verde","Hubo empate"],"correctIndex":0,"visual":{"tipo":"barras","datos":[{"etiqueta":"Rojo","valor":3},{"etiqueta":"Azul","valor":5},{"etiqueta":"Verde","valor":2}]},"ayuda":{"pista":"El que ganó es el de la barra más larga. Mira el dibujo antes de contar.","pasos":["Cada barra muestra cuántos votos tuvo cada opción.","La barra más larga es la que más votos tuvo: esa ganó.","Si no se ve claro, mira el número que hay al final de cada barra."],"ojo":"No importa cuál te guste más a ti: la que gana es la que más votos sacó."}}'::jsonb, 6);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('e0da0b73-4c84-4939-8554-718a89b59f3e'::uuid, 'multiple_choice', 'En la votación de colores, ¿cuál ganó?', '{"options":["Rojo","Azul","Verde","Hubo empate"],"correctIndex":0,"visual":{"tipo":"barras","datos":[{"etiqueta":"Rojo","valor":6},{"etiqueta":"Azul","valor":2},{"etiqueta":"Verde","valor":4}]},"ayuda":{"pista":"El que ganó es el de la barra más larga. Mira el dibujo antes de contar.","pasos":["Cada barra muestra cuántos votos tuvo cada opción.","La barra más larga es la que más votos tuvo: esa ganó.","Si no se ve claro, mira el número que hay al final de cada barra."],"ojo":"No importa cuál te guste más a ti: la que gana es la que más votos sacó."}}'::jsonb, 6);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('e0da0b73-4c84-4939-8554-718a89b59f3e'::uuid, 'multiple_choice', 'Votamos el animal favorito. ¿Cuál ganó?', '{"options":["Gato","Perro","Pez","Hubo empate"],"correctIndex":0,"visual":{"tipo":"barras","datos":[{"etiqueta":"Perro","valor":4},{"etiqueta":"Gato","valor":7},{"etiqueta":"Pez","valor":1}]},"ayuda":{"pista":"El que ganó es el de la barra más larga. Mira el dibujo antes de contar.","pasos":["Cada barra muestra cuántos votos tuvo cada opción.","La barra más larga es la que más votos tuvo: esa ganó.","Si no se ve claro, mira el número que hay al final de cada barra."],"ojo":"No importa cuál te guste más a ti: la que gana es la que más votos sacó."}}'::jsonb, 6);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('e0da0b73-4c84-4939-8554-718a89b59f3e'::uuid, 'multiple_choice', 'Votamos el color favorito. ¿Cuál tuvo menos?', '{"options":["Verde","Rojo","Azul","Todos igual"],"correctIndex":0,"visual":{"tipo":"barras","datos":[{"etiqueta":"Rojo","valor":3},{"etiqueta":"Azul","valor":5},{"etiqueta":"Verde","valor":2}]},"ayuda":{"pista":"El que tuvo menos es el de la barra MÁS CORTA.","pasos":["Cada barra dice cuántos votos tuvo esa opción.","La barra más corta es la que menos votos sacó.","Compara las tres y quédate con la más pequeña."],"ojo":"Aquí piden la que tuvo MENOS. Contestar con la ganadora es el error de siempre."}}'::jsonb, 7);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('e0da0b73-4c84-4939-8554-718a89b59f3e'::uuid, 'multiple_choice', 'Votamos el animal favorito. ¿Cuál tuvo menos?', '{"options":["Pez","Perro","Gato","Todos igual"],"correctIndex":0,"visual":{"tipo":"barras","datos":[{"etiqueta":"Perro","valor":4},{"etiqueta":"Gato","valor":7},{"etiqueta":"Pez","valor":1}]},"ayuda":{"pista":"El que tuvo menos es el de la barra MÁS CORTA.","pasos":["Cada barra dice cuántos votos tuvo esa opción.","La barra más corta es la que menos votos sacó.","Compara las tres y quédate con la más pequeña."],"ojo":"Aquí piden la que tuvo MENOS. Contestar con la ganadora es el error de siempre."}}'::jsonb, 7);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('e0da0b73-4c84-4939-8554-718a89b59f3e'::uuid, 'multiple_choice', 'Votamos el deporte favorito. ¿Cuál tuvo menos?', '{"options":["Natación","Fútbol","Ciclismo","Todos igual"],"correctIndex":0,"visual":{"tipo":"barras","datos":[{"etiqueta":"Fútbol","valor":8},{"etiqueta":"Natación","valor":3},{"etiqueta":"Ciclismo","valor":5}]},"ayuda":{"pista":"El que tuvo menos es el de la barra MÁS CORTA.","pasos":["Cada barra dice cuántos votos tuvo esa opción.","La barra más corta es la que menos votos sacó.","Compara las tres y quédate con la más pequeña."],"ojo":"Aquí piden la que tuvo MENOS. Contestar con la ganadora es el error de siempre."}}'::jsonb, 7);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('e0da0b73-4c84-4939-8554-718a89b59f3e'::uuid, 'multiple_choice', 'Votamos el color. ¿Cuántos niños votaron en total?', '{"options":["10","8","9","11"],"correctIndex":0,"visual":{"tipo":"barras","datos":[{"etiqueta":"Rojo","valor":3},{"etiqueta":"Azul","valor":5},{"etiqueta":"Verde","valor":2}]},"ayuda":{"pista":"El total son todos los votos juntos: hay que sumar las tres barras.","pasos":["Cada barra dice cuántos votaron por esa opción.","Como cada niño votó una sola vez, todos los votos juntos son todos los niños.","Súmalos de a dos: primero dos barras, y a ese resultado le sumas la tercera."],"ojo":"El total no es la barra más larga: es la suma de todas."}}'::jsonb, 8);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('e0da0b73-4c84-4939-8554-718a89b59f3e'::uuid, 'multiple_choice', 'Votamos el animal. ¿Cuántos niños respondieron?', '{"options":["12","11","10","13"],"correctIndex":0,"visual":{"tipo":"barras","datos":[{"etiqueta":"Perro","valor":4},{"etiqueta":"Gato","valor":7},{"etiqueta":"Pez","valor":1}]},"ayuda":{"pista":"El total son todos los votos juntos: hay que sumar las tres barras.","pasos":["Cada barra dice cuántos votaron por esa opción.","Como cada niño votó una sola vez, todos los votos juntos son todos los niños.","Súmalos de a dos: primero dos barras, y a ese resultado le sumas la tercera."],"ojo":"El total no es la barra más larga: es la suma de todas."}}'::jsonb, 8);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('e0da0b73-4c84-4939-8554-718a89b59f3e'::uuid, 'multiple_choice', 'Votamos la fruta. ¿Cuántos niños votaron en total?', '{"options":["12","10","11","13"],"correctIndex":0,"visual":{"tipo":"barras","datos":[{"etiqueta":"Mango","valor":6},{"etiqueta":"Piña","valor":2},{"etiqueta":"Mora","valor":4}]},"ayuda":{"pista":"El total son todos los votos juntos: hay que sumar las tres barras.","pasos":["Cada barra dice cuántos votaron por esa opción.","Como cada niño votó una sola vez, todos los votos juntos son todos los niños.","Súmalos de a dos: primero dos barras, y a ese resultado le sumas la tercera."],"ojo":"El total no es la barra más larga: es la suma de todas."}}'::jsonb, 8);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('e0da0b73-4c84-4939-8554-718a89b59f3e'::uuid, 'multiple_choice', 'Votamos la fruta favorita. ¿Cuál gustó más?', '{"options":["Mango y banano","Solo el mango","La papaya","Solo el banano"],"correctIndex":0,"visual":{"tipo":"barras","datos":[{"etiqueta":"Mango","valor":7},{"etiqueta":"Banano","valor":7},{"etiqueta":"Papaya","valor":2}]},"ayuda":{"pista":"Antes de contestar, fíjate si hay DOS barras que llegan igual de lejos.","pasos":["Mira las barras y busca la más larga.","Pero revisa si hay otra que llegue exactamente igual.","Cuando dos llegan al mismo punto, las dos ganaron: hubo empate."],"ojo":"Cuando hay empate, contestar con una sola de las dos deja a la otra por fuera."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('e0da0b73-4c84-4939-8554-718a89b59f3e'::uuid, 'multiple_choice', 'Votamos el color favorito. ¿Cuál gustó más?', '{"options":["Rojo y azul","Solo el rojo","El verde","Solo el azul"],"correctIndex":0,"visual":{"tipo":"barras","datos":[{"etiqueta":"Rojo","valor":5},{"etiqueta":"Azul","valor":5},{"etiqueta":"Verde","valor":1}]},"ayuda":{"pista":"Antes de contestar, fíjate si hay DOS barras que llegan igual de lejos.","pasos":["Mira las barras y busca la más larga.","Pero revisa si hay otra que llegue exactamente igual.","Cuando dos llegan al mismo punto, las dos ganaron: hubo empate."],"ojo":"Cuando hay empate, contestar con una sola de las dos deja a la otra por fuera."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('e0da0b73-4c84-4939-8554-718a89b59f3e'::uuid, 'multiple_choice', 'Votamos el juego favorito. ¿Cuál gustó más?', '{"options":["Balón y rompecabezas","Solo el balón","El lego","Solo el rompecabezas"],"correctIndex":0,"visual":{"tipo":"barras","datos":[{"etiqueta":"Lego","valor":3},{"etiqueta":"Balón","valor":6},{"etiqueta":"Rompecabezas","valor":6}]},"ayuda":{"pista":"Antes de contestar, fíjate si hay DOS barras que llegan igual de lejos.","pasos":["Mira las barras y busca la más larga.","Pero revisa si hay otra que llegue exactamente igual.","Cuando dos llegan al mismo punto, las dos ganaron: hubo empate."],"ojo":"Cuando hay empate, contestar con una sola de las dos deja a la otra por fuera."}}'::jsonb, 9);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('e0da0b73-4c84-4939-8554-718a89b59f3e'::uuid, 'multiple_choice', '¿Cuántos niños MÁS prefieren mango que papaya?', '{"options":["5","9","4","2"],"correctIndex":0,"visual":{"tipo":"barras","datos":[{"etiqueta":"Mango","valor":7},{"etiqueta":"Papaya","valor":2}]},"ayuda":{"pista":"«Cuántos MÁS» pregunta por la diferencia: se resta la barra corta de la larga.","pasos":["Mira las dos barras que te nombran y fíjate cuál es más larga.","La pregunta es cuánto le sobra a la larga por encima de la corta.","Eso se averigua restando el número pequeño del grande."],"ojo":"No es cuántos votaron en total: es cuántos de diferencia hay entre las dos."}}'::jsonb, 10);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('e0da0b73-4c84-4939-8554-718a89b59f3e'::uuid, 'multiple_choice', '¿Cuántos niños MÁS prefieren gato que pez?', '{"options":["6","8","5","1"],"correctIndex":0,"visual":{"tipo":"barras","datos":[{"etiqueta":"Gato","valor":7},{"etiqueta":"Pez","valor":1}]},"ayuda":{"pista":"«Cuántos MÁS» pregunta por la diferencia: se resta la barra corta de la larga.","pasos":["Mira las dos barras que te nombran y fíjate cuál es más larga.","La pregunta es cuánto le sobra a la larga por encima de la corta.","Eso se averigua restando el número pequeño del grande."],"ojo":"No es cuántos votaron en total: es cuántos de diferencia hay entre las dos."}}'::jsonb, 10);
insert into exercises (evidence_id, type, prompt, config, order_in_lesson) values ('e0da0b73-4c84-4939-8554-718a89b59f3e'::uuid, 'multiple_choice', '¿Cuántos niños MÁS prefieren fútbol que natación?', '{"options":["5","11","4","3"],"correctIndex":0,"visual":{"tipo":"barras","datos":[{"etiqueta":"Fútbol","valor":8},{"etiqueta":"Natación","valor":3}]},"ayuda":{"pista":"«Cuántos MÁS» pregunta por la diferencia: se resta la barra corta de la larga.","pasos":["Mira las dos barras que te nombran y fíjate cuál es más larga.","La pregunta es cuánto le sobra a la larga por encima de la corta.","Eso se averigua restando el número pequeño del grande."],"ojo":"No es cuántos votaron en total: es cuántos de diferencia hay entre las dos."}}'::jsonb, 10);
